	(1, 'eeww', 'eeww', 'eee', 'dd', 'vvv', NULL, NULL, 'articles/jMYQNZjh4HTpK5u1GyAGnUJlrmsLR6uuSytCXKhc.png', NULL, NULL, NULL, NULL, 5, NULL, 1, NULL, 'published', 0, 0, 0, '2026-08-18 03:30:17', NULL, '2026-08-18 06:15:09', '2026-08-18 06:15:09'),
	(2, 'www', 'www', 'ww', 'dd', 'ccc', NULL, NULL, 'articles/rv0wyHLRJ5slQX9p7R56m6uEGLaHJCfWCAbgzUm4.png', NULL, NULL, NULL, NULL, 5, NULL, 1, NULL, 'draft', 1, 0, 0, NULL, '2026-08-18 03:01:38', '2026-08-18 06:15:16', '2026-08-18 06:15:16'),
	(3, 'ইরান–যুক্তরাষ্ট্র যুদ্ধবিরতি শেষ, ৯১ ডলারের ওপরে উঠল তেলের দাম', 'ইরনযকতরষটর-যদধবরত-শষ-৯১-ডলরর-ওপর-উঠল-তলর-দম', NULL, NULL, 'বিশ্ববাজারে আজ মঙ্গলবার তেলের দাম বেড়ে ছয় সপ্তাহের মধ্যে সর্বোচ্চ পর্যায়ে উঠেছে। এশিয়ার বাজারে আজ সকালে ব্রেন্ট ক্রুডের দাম ব্যারেলপ্রতি ৯১ দশমিক শূন্য ৬ ডলারে ওঠে। আগের দিনও দাম বেড়েছিল ২ ডলারের বেশি।\r\n\r\nযুক্তরাষ্ট্র ও ইরানের যুদ্ধবিরতির মেয়াদ শেষ হওয়ার পর মধ্যপ্রাচ্যে আবারও উত্তেজনা বেড়েছে। তার জেরে চলতি সপ্তাহের প্রথম দুই দিনে তেলের দাম বেড়েছে। ফলে তেলের দাম আবারও ব্যারেলপ্রতি ৯০ ডলার ছাড়িয়ে গেছে। খবর রয়টার্সের\r\n\r\n২০২৬ সালের ৮ এপ্রিল যুক্তরাষ্ট্র ও ইরানের মধ্যে প্রাথমিকভাবে দুই সপ্তাহের যুদ্ধবিরতি হয়। পরবর্তীকালে পাকিস্তানের মধ্যস্থতায় দুই দেশের মধ্যে আলোচনা হয়। ১৭ জুন ৬০ দিনের যুদ্ধবিরতির সমঝোতা স্মারক (এমওইউ) স্বাক্ষরিত হয়। এর মেয়াদ যে বাড়ানো হবে, তা নিয়ে উভয়পক্ষ সাময়িকভাবে সম্মত হয়েছিল। কিন্তু সেই মেয়াদ আর বাড়ছে না।', NULL, NULL, 'articles/WTP2t5wvI4oEGng1QqV9DBZn9Y3wfc1fqyLgmru0.jpg', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 0, 1, 0, '2026-08-18 05:17:47', '2026-08-18 05:17:17', '2026-08-22 06:11:53', NULL),
	(4, 'rafan', 'rafan', NULL, NULL, 'road', NULL, NULL, 'articles/sAgxojifSwGIVxegweOWyL8lZlTflD9DFPw3WgWf.png', NULL, NULL, NULL, NULL, 11, NULL, 1, NULL, 'draft', 0, 0, 0, NULL, '2026-08-21 10:23:31', '2026-08-21 11:30:38', '2026-08-21 11:30:38'),
	(5, 'raha', 'raha', NULL, NULL, 'building', NULL, NULL, 'articles/dQKE0wogdFrBIgyn7RKBfUgqbOmDMDJjYBbSDo4F.png', NULL, NULL, NULL, NULL, 5, NULL, 1, NULL, 'draft', 0, 0, 0, NULL, '2026-08-21 10:26:14', '2026-08-21 11:30:33', '2026-08-21 11:30:33'),
	(6, 'rashaed', 'rashaed', NULL, NULL, 'fan', NULL, NULL, 'articles/yC3gvrIYL6dTgZnsxdD6rp8r9jAz0CJGdjL15xtH.jpg', NULL, NULL, NULL, NULL, 17, NULL, 1, NULL, 'draft', 0, 0, 0, NULL, '2026-08-21 10:28:15', '2026-08-21 11:30:29', '2026-08-21 11:30:29'),
	(7, 'bonna', 'bonna', NULL, NULL, 'giass', NULL, NULL, 'articles/JwmcSSpEXijvfqrk8g1s3R2sbZQg6y7ljwL2fqAf.png', NULL, NULL, NULL, NULL, 1, NULL, 1, NULL, 'published', 0, 0, 0, '2026-08-21 10:59:03', '2026-08-21 10:29:41', '2026-08-21 11:30:25', '2026-08-21 11:30:25'),
	(8, 'ময়মনসিংহে পাচারের সময় বাজারের ব্যাগ থেকে দুটি বিপন্ন লজ্জাবতী বানর উদ্ধার', 'ময়মনসহ-পচরর-সময়-বজরর-বযগ-থক-দট-বপনন-লজজবত-বনর-উদধর', NULL, 'অভিনন্দন বার্তায় মালদ্বীপের প্রেসিডেন্ট উল্লেখ করেন, বিগত ৩৫ বছরের মধ্যে প্রথম প্রতিদ্বন্দ্বিতাপূর্ণ রাষ্ট্রপতি', 'ময়মনসিংহের হালুয়াঘাটে পাচারের সময় বাজারের ব্যাগে রাখা দুটি লজ্জাবতী বানর উদ্ধার করেছে বন অধিদপ্তরের বন্য প্রাণী অপরাধ দমন ইউনিট। তবে অভিযানের বিষয়টি টের পেয়ে পাচারকারীরা পালিয়ে যাওয়ায় কাউকে আটক করা সম্ভব হয়নি।\r\n\r\nশুক্রবার বিকেল সাড়ে পাঁচটার দিকে হালুয়াঘাট-ময়মনসিংহ আঞ্চলিক মহাসড়কের হালুয়াঘাট বাসস্ট্যান্ড এলাকায় এ অভিযান চালানো হয়। উদ্ধার করা বানর দুটিকে সিলেটের লাউয়াছড়া জাতীয় উদ্যানে অবমুক্ত করা হবে বলে জানিয়েছে বন বিভাগ।', NULL, NULL, 'articles/hyRhYHUSnOAgD66XNVau3H3JMluZANGdKkmaowr1.jpg', NULL, NULL, NULL, NULL, 5, 7, 1, NULL, 'published', 0, 1, 11, '2026-08-21 11:58:35', '2026-08-21 11:58:35', '2026-08-23 09:24:34', NULL),
	(9, 'বঙ্গভবনে রাষ্ট্রপতি ও মন্ত্রীদের শপথ গ্রহণ', 'বঙগভবন-রষটরপত-ও-মনতরদর-শপথ-গরহণ', NULL, NULL, 'দেশের ২৩তম রাষ্ট্রপতি হিসেবে শপথ নিলেন মির্জা ফখরুল ইসলাম আলমগীর। শপথ নিয়েছেন নতুন ৪ মন্ত্রী ও ২ প্রতিমন্ত্রী। ২১ আগস্ট সন্ধ্যা সাড়ে ৭টায় বঙ্গভবনের দরবার হলে উপস্থিত ছিলেন প্রধানমন্ত্রী তারেক রহমান, সাবেক অন্তর্বর্তী সরকারের প্রধান উপদেষ্টা অধ্যাপক মুহাম্মদ ইউনূসসহ রাষ্ট্রের শীর্ষ ব্যক্তিরা।', NULL, NULL, 'articles/1f7wM9AXdJsdSznlsLn8tFBq2fDGwVvgFgIhApKX.png', NULL, NULL, NULL, NULL, 5, NULL, 1, NULL, 'published', 0, 0, 0, '2026-08-21 12:22:30', '2026-08-21 12:22:30', '2026-08-22 06:12:56', NULL),
	(10, 'জহির উদ্দিন স্বপন প্রধানমন্ত্রীর উপদেষ্টা, বিমান থেকে খাদ্যমন্ত্রী আফরোজা খানম', 'জহর-উদদন-সবপন-পরধনমনতরর-উপদষট-বমন-থক-খদযমনতর-আফরজ-খনম', NULL, 'অভিনন্দন বার্তায় মালদ্বীপের প্রেসিডেন্ট উল্লেখ করেন, বিগত ৩৫ বছরের মধ্যে প্রথম প্রতিদ্বন্দ্বিতাপূর্ণ রাষ্ট্রপতি', 'সরকার গঠনের ছয় মাস পর মন্ত্রিসভার আকার বাড়ল। নতুন করে পাঁচজন মন্ত্রিসভায় যুক্ত হলেন। আর একজন প্রতিমন্ত্রী থেকে মন্ত্রী হয়েছেন। সব মিলিয়ে চারজন নতুন মন্ত্রী এবং দুজন প্রতিমন্ত্রী শপথ নিয়েছেন। আজ রাতেই মন্ত্রিসভার কয়েকজন সদস্যের দপ্তর বণ্টন ও পুনর্বণ্টন করা হয়েছে।\r\n\r\nএর মধ্যে তথ্যমন্ত্রী জহির উদ্দিন স্বপনকে প্রধানমন্ত্রীর উপদেষ্টা করা হয়েছে। আর বিএনপির জোটসঙ্গী বাংলাদেশ জাতীয় পার্টির (বিজেপি) চেয়ারম্যান আন্দালিভ রহমান পার্থ তথ্য ও সম্প্রচার মন্ত্রণালয়ের দায়িত্ব পেয়েছেন। অন্যদিকে প্রতিমন্ত্রী থেকে মন্ত্রী হওয়া রশিদুজ্জামান মিল্লাত বেসামরিক বিমান পরিবহন ও পর্যটন মন্ত্রণালয়ের মন্ত্রীর দায়িত্ব পেয়েছেন (আগে এই মন্ত্রণালয়েরই প্রতিমন্ত্রী ছিলেন)। আর এই মন্ত্রণালয়ের মন্ত্রী আফরোজা খানমকে (রিতা) খাদ্য মন্ত্রণালয়ের মন্ত্রী করা হয়েছে। বর্তমানে জনপ্রশাসন মন্ত্রণালয়ের পাশাপাশি খাদ্য মন্ত্রণালয়ের প্রতিমন্ত্রীর দায়িত্ব পালন করছেন মো. আব্দুল বারী।', NULL, NULL, 'articles/VzOk7ECmTuoBLDLzlg7lkXIrdioGgDmNVsBppa4Q.jpg', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 0, 0, 1, '2026-08-21 12:28:06', '2026-08-21 12:28:06', '2026-08-22 11:58:10', NULL),
	(11, 'রাষ্ট্রপতি মির্জা ফখরুলকে মালদ্বীপের প্রেসিডেন্টের অভিনন্দন', 'রষটরপত-মরজ-ফখরলক-মলদবপর-পরসডনটর-অভননদন', NULL, 'অভিনন্দন বার্তায় মালদ্বীপের প্রেসিডেন্ট উল্লেখ করেন, বিগত ৩৫ বছরের মধ্যে প্রথম প্রতিদ্বন্দ্বিতাপূর্ণ রাষ্ট্রপতি', 'অভিনন্দন বার্তায় মালদ্বীপের প্রেসিডেন্ট উল্লেখ করেন, বিগত ৩৫ বছরের মধ্যে প্রথম প্রতিদ্বন্দ্বিতাপূর্ণ রাষ্ট্রপতি নির্বাচন বাংলাদেশের গণতান্ত্রিক অভিযাত্রায় একটি গুরুত্বপূর্ণ মাইলফলক এবং নবনির্বাচিত রাষ্ট্রপতির প্রতি দেশের জনগণের আস্থার প্রতিফলন।\r\n\r\nপ্রেসিডেন্ট মুইজ্জু আরও বলেন, বাংলাদেশ ও মালদ্বীপের মধ্যকার দীর্ঘস্থায়ী সম্পর্ক শক্তিশালী ঐতিহাসিক বন্ধন এবং আঞ্চলিক স্থিতিশীলতা ও উন্নয়নের প্রতি অভিন্ন অঙ্গীকারের ভিত্তিতে প্রতিষ্ঠিত।', NULL, NULL, 'articles/ZLtqTKfHGKzPcS0vqNTE7bk6aHcUm8mlX77e4Nee.png', NULL, NULL, NULL, NULL, 17, NULL, 1, NULL, 'published', 0, 1, 5, '2026-08-21 23:47:45', '2026-08-21 23:47:45', '2026-08-23 08:54:49', NULL),
	(12, 'যেকোনো নতুন মার্কিন হুমকির বিরুদ্ধে ধ্বংসাত্মক জবাব দেয়া হবে: ইরান', 'যকন-নতন-মরকন-হমকর-বরদধ-ধবসতমক-জবব-দয-হব-ইরন', NULL, 'কোনো খাবার ও পানি ছাড়াই টানা ১০ দিন সাগরে ভাসতে থাকেন আরোহীরা। এর মধ্যে মারা যান ৯ বাংলাদেশী। তাদের সবার মরদেহ ফেলে দেয়া হয় সাগরেই। বেঁচে থাকা বাকি', 'ইরানের ওপর যুক্তরাষ্ট্রের সম্ভাব্য এ নিষেধাজ্ঞার হুমকিকে বিশ্বের সব স্বাধীন ও সার্বভৌম সরকারের বিরুদ্ধে ওয়াশিংটনের যুদ্ধ ঘোষণা হিসেবে অভিহিত করেছেন দেশটির পররাষ্ট্র মন্ত্রণালয়ের মুখপাত্র ইসমাইল বাঘাই। তিনি বলেন, নতুন এ বিধিনিষেধের ঘোষণাটি জাতিসংঘের স্বাধীন সদস্য রাষ্ট্রগুলোর ওপর মার্কিন যুক্তরাষ্ট্রের নিজস্ব সার্বভৌমত্ব চাপিয়ে দেয়ার একটি বহিঃপ্রকাশ ছাড়া আর কিছুই নয়।\r\n\r\nতিনি উল্লেখ করেন, কোনো স্বাধীন সার্বভৌম দেশের অধীনে পরিচালিত বিদেশী ব্যাংক, ব্যবসায়ী প্রতিষ্ঠান বা বিমানবন্দরগুলোকে তৃতীয় কোনো রাষ্ট্রের সঙ্গে বৈধ বাণিজ্য পরিচালনা করা থেকে বিরত রাখতে বাধ্য করার অধিকার অন্য কোনো সরকারের নেই। এ ধরণের নিষেধাজ্ঞার আন্তর্জাতিক আইনে কোনো স্থান নেই এবং এটি জাতিসংঘ সনদের অনুচ্ছেদ ২, অনুচ্ছেদ ১-এ বর্ণিত সার্বভৌম সমতার মৌলিক নীতিকে স্পষ্টভাবে লঙ্ঘন করে।\r\n\r\nঅর্থনৈতিক চাপ সৃষ্টিকে আন্তর্জাতিক অপরাধ হিসেবে বর্ণনা করে বাঘাই সতর্ক করেন, নৌঅবরোধ ও নিষেধাজ্ঞার মিশ্রণ অন্য দেশের স্বাধীনতা ও সার্বভৌমত্বকে পুরোপুরি বিপন্ন করে তোলে। এ ধরণের ভয়ভীতির কাছে নতি স্বীকার করাকে জাতীয় সার্বভৌমত্বের বিলুপ্তি এবং উপনিবেশবাদের মারাত্মক পুনরাবৃত্তি হিসেবে চিহ্নিত করেন তিনি।\r\n\r\nইরানের সশস্ত্র বাহিনীর চিফ অব স্টাফ মেজর জেনারেল আলী অবদুল্লাহি সতর্ক করে বলেছেন, শত্রুভাবাপন্ন যেকোনো পদক্ষেপের জবাবে সামরিক ও কৌশলগতভাবে কড়া প্রতিক্রিয়া দেখানো হবে। দেশটির গণমাধ্যমে তার উদ্ধৃতি দিয়ে বলা হয়, স্থল, আকাশ, সমুদ্র, বিমান প্রতিরক্ষা এবং সাইবার স্পেসে পূর্ণ প্রস্তুতি নিয়ে শত্রুর নতুন হুমকির বিরুদ্ধে শাস্তিমূলক ও ধ্বংসাত্মক প্রতিক্রিয়া জানাবে ইরানের সশস্ত্র বাহিনী।\r\n\r\nমার্কিন প্রশাসনের পক্ষ থেকে যুদ্ধের শুরুতে ইরানের পারমাণবিক কার্যক্রম সম্পূর্ণ অকার্যকর করা এবং শাসনব্যবস্থায় রদবদল ঘটানোর যে লক্ষ্য নির্ধারণ করা হয়েছিল, তা এখনো বাস্তবায়িত হয়নি। প্রায় ছয় মাস ধরে চলা মার্কিন হামলায় ইরানের অভ্যন্তরীণ অর্থনীতি ও সামরিক কাঠামোর ব্যাপক ক্ষতি হলেও কৌশলগত গুরুত্বসম্পন্ন হরমুজ প্রণালিতে বাণিজ্যিক জাহাজ চলাচল এবং আঞ্চলিক সামরিক ভারসাম্যে প্রভাব ফেলার মতো ক্ষেপণাস্ত্র ও ড্রোন সক্ষমতা এখনো তেহরানের নিয়ন্ত্রণে রয়েছে। অন্যদিকে দীর্ঘমেয়াদি এ সংঘাতের কারণে আন্তর্জাতিক জ্বালানি বাজারে অস্থিরতার ফলে যুক্তরাষ্ট্রে অভ্যন্তরীণ বাজারে গ্যাসের মূল্য বৃদ্ধি পেয়েছে, যা দেশটির বর্তমান প্রশাসনের জনপ্রিয়তায় প্রভাব ফেলেছে।', NULL, NULL, 'articles/uvMlWdYUJ1WYPKVuuvs0tDitM8fOD0fcoNK56nMI.jpg', NULL, NULL, NULL, NULL, 5, 22, 1, NULL, 'published', 0, 1, 8, '2026-08-21 23:51:13', '2026-08-21 23:50:50', '2026-08-26 07:13:41', NULL),
	(13, 'ইউরোপ-যাত্রায় ৯ রুটে প্রাণ গেছে ২ হাজার ১৮৮ বাংলাদেশীর', 'ইউরপ-যতরয়-৯-রট-পরণ-গছ-২-হজর-১৮৮-বলদশর', '২০১৫ থেকে ২০২৫ সাল', 'ইউরোপে উন্নত জীবনের স্বপ্ন নিয়ে গত ৩ আগস্ট লিবিয়ার তবরুক থেকে নৌকায় উঠেছিলেন ৩৮ বাংলাদেশী। ভূমধ্যসাগর পাড়ি দিয়ে গ্রিসে পৌঁছার লক্ষ্য ছিল রাবারের নৌকাটির।', 'এটি কেবল একটি পরিবারের গল্প নয়, অবৈধ বা অনিয়মিত পথে ইউরোপে যাওয়ার চেষ্টা করতে গিয়ে গত এক দশকে এমন পরিণতির শিকার হয়েছেন হাজারো বাংলাদেশী। আন্তর্জাতিক অভিবাসন সংস্থা আইওএমের ‘মিসিং মাইগ্র্যান্টস প্রজেক্ট’-এর গ্লোবাল ডেটাবেজ পর্যালোচনায় দেখা যায়, ২০১৫ থেকে ২০২৫ সাল পর্যন্ত বিশ্বের নয়টি অনিয়মিত অভিবাসনপথে ঘটে যাওয়া ৮৪টি পৃথক দুর্ঘটনায় অন্তত ১ হাজার ৩২৯ বাংলাদেশী মারা গেছেন এবং আরো ৮৫৯ জন নিখোঁজ রয়েছেন। অর্থাৎ গত এক দশকে ২ হাজার ১৮৮ বাংলাদেশীর কোনো না কোনোভাবে মৃত্যু বা নিখোঁজ হওয়ার ঘটনা নথিভুক্ত হয়েছে।\r\n\r\nএ মৃত্যুর মানচিত্রে সবচেয়ে ভয়ংকর পথটি ভূমধ্যসাগর। লিবিয়া বা তিউনিসিয়া থেকে এ সাগর পাড়ি দিয়ে ইতালি পৌঁছার চেষ্টায় ১ হাজার ১৭১ বাংলাদেশী মারা গেছেন এবং নিখোঁজ হয়েছেন ৭৭৩ জন। অর্থাৎ মোট মৃত্যু ও নিখোঁজের প্রায় ৯০ শতাংশেরও বেশি ঘটেছে শুধু এ রুটে। ভূমধ্যসাগর পাড়ি দিয়ে ইউরোপ-যাত্রায় ভয়াবহতার সবচেয়ে বড় উদাহরণ ২০১৫ সাল। ওই বছর মাত্র চারটি ঘটনায় ৯২৪ বাংলাদেশী নিহত ও ৩৬৩ জনকে নিখোঁজ হিসেবে রেকর্ড করা হয়। ফলে এক বছরেই এ রুটে মৃত ও নিখোঁজের সংখ্যা দাঁড়ায় ১ হাজার ২৮৭-এ।\r\n\r\nআন্তর্জাতিক সংস্থাগুলোর মতে, এ সংখ্যা প্রকৃত চিত্রের চেয়ে কম। কারণ সমুদ্রপথে অনেক নৌযান নিখোঁজ হলেও যাত্রী বা মৃতের সংখ্যা নিশ্চিত করা সম্ভব হয় না। আইওএমের ভাষ্য অনুযায়ীও অভিবাসনপথে মৃত্যু ও নিখোঁজের তথ্য সংগ্রহে বড় ধরনের সীমাবদ্ধতা রয়েছে। বিশেষ করে সমুদ্রে নিখোঁজদের সংখ্যা নিরূপণ অত্যন্ত কঠিন।\r\n\r\nঅভিবাসনের স্বপ্নে যারা দেশ ছাড়েন, তাদের কাছে ইউরোপ অনেক সময় শুধু একটি গন্তব্য নয়; পরিবারের অর্থনৈতিক মুক্তির প্রতিশ্রুতি। জমি বিক্রি, ঋণ নেয়া কিংবা স্বজনদের কাছ থেকে টাকা সংগ্রহ করে অনেকেই দালাল চক্রের মাধ্যমে প্রথমে মধ্যপ্রাচ্য বা উত্তর আফ্রিকার কোনো দেশে পৌঁছান। এরপর শুরু হয় ইউরোপের উদ্দেশে বিপজ্জনক এ যাত্রা।\r\n\r\nসবাই অবশ্য সাগরে পৌঁছতে পারেন না। আইওএমের তথ্য অনুযায়ী, সাহারা মরুভূমি পাড়ি দিতে গিয়েই অন্তত ৩৮ বাংলাদেশীর মৃত্যু হয়েছে। পশ্চিম আফ্রিকা বা আটলান্টিক মহাসাগর হয়ে স্পেনের ক্যানারি দ্বীপপুঞ্জে পৌঁছার পথে মারা গেছেন আরো একজন, নিখোঁজ হয়েছেন ২২ জন। তুরস্ক-ইউরোপ স্থলপথে ২০ বাংলাদেশীর মৃত্যুর তথ্যও নথিভুক্ত হয়েছে।', NULL, NULL, 'articles/7S3aCt2wCf0mUSXOzRiimOfwosnZKfe0foTOJrId.jpg', NULL, NULL, NULL, NULL, 17, NULL, 1, NULL, 'published', 0, 1, 50, '2026-08-21 23:54:40', '2026-08-21 23:54:10', '2026-08-29 09:21:47', NULL),
	(14, 'পুলিশের সোর্স পরিচয়ে আসামির স্বজনদের থেকে অর্থ আদায়, কারাদণ্ড', 'পলশর-সরস-পরচয়-আসমর-সবজনদর-থক-অরথ-আদয়-করদণড', NULL, 'পুলিশের সোর্স পরিচয়ে বিভিন্ন মামলার আসামিদের স্বজনদের কাছ থেকে টাকা হাতিয়ে নেওয়ার দায়ে', 'আজ শনিবার ঢাকা মেট্রোপলিটন পুলিশের (ডিএমপি) গণমাধ্যম ও জনসংযোগ বিভাগ থেকে পাঠানো এক সংবাদ বিজ্ঞপ্তিতে এসব তথ্য জানানো হয়।\r\n\r\nসংবাদ বিজ্ঞপ্তিতে পুলিশ জানায়, দীর্ঘদিন ধরে নজির হোসেন নিজেকে পুলিশের সোর্স হিসেবে পরিচয় দিয়ে প্রতারণা করে আসছিলেন। মতিঝিল, পল্টন এলাকা ও স্পেশাল ম্যাজিস্ট্রেট আদালতের বিভিন্ন মামলার আসামিদের স্বজনদের সঙ্গে যোগাযোগ করতেন। সংশ্লিষ্ট মামলায় সহায়তা, জামিন করিয়ে দেওয়া, সাজা কমিয়ে দেওয়ার আশ্বাস দিয়ে তাঁদের কাছ থেকে অর্থ নিতেন।\r\n\r\nপল্টন মডেল থানা-পুলিশ সূত্রে জানা গেছে, আটক করার পর নজির হোসেনকে মতিঝিল বিভাগের স্পেশাল মেট্রোপলিটন ম্যাজিস্ট্রেটের ভ্রাম্যমাণ আদালতে তোলা হয়। আদালত তাঁকে দুই বছরের সশ্রম কারাদণ্ড দেন।', NULL, NULL, 'articles/uLARwbsWMxqqeD7v5KuXeWkjs9V0bPR0NBxNRIJR.png', NULL, NULL, NULL, NULL, 17, 6, 1, NULL, 'published', 0, 0, 12, '2026-08-22 05:08:11', '2026-08-22 05:08:11', '2026-08-25 06:41:07', NULL),
	(15, 'জাতীয় স্বার্থে ছাড় নয়, ভারতের সঙ্গে ভারসাম্যপূর্ণ সম্পর্ক চায় বাংলাদেশ: পররাষ্ট্র প্রতিমন্ত্রী', 'জতয়-সবরথ-ছড়-নয়-ভরতর-সঙগ-ভরসমযপরণ-সমপরক-চয়-বলদশ-পররষটর-পরতমনতর', NULL, 'পররাষ্ট্র প্রতিমন্ত্রী হুমায়ুন কবির বলেন, বিগত কয়েক মাসে প্রধানমন্ত্রীর নেতৃত্বে দেশের পররাষ্ট্রনীতিতে একটি নতুন কৌশলগত কাঠামো দাঁড় করানো হয়েছে।', 'পররাষ্ট্র প্রতিমন্ত্রী বলেন, বিগত কয়েক মাসে প্রধানমন্ত্রীর নেতৃত্বে দেশের পররাষ্ট্রনীতিতে একটি নতুন কৌশলগত কাঠামো দাঁড় করানো হয়েছে। ওয়াশিংটন, বেইজিং বা মধ্যপ্রাচ্য—সব দেশের সঙ্গে ভারসাম্যপূর্ণ দ্বিপক্ষীয় সম্পর্ক বজায় রাখা হচ্ছে। এতে বাংলাদেশের জাতীয় স্বার্থকে সর্বোচ্চ অগ্রাধিকার দেয়া হচ্ছে।\r\n\r\nক্ষমতাচ্যুত সাবেক প্রধানমন্ত্রী শেখ হাসিনাকে দেশে ফিরিয়ে আনা এবং দ্বিপক্ষীয় সফর প্রসঙ্গে সাংবাদিকদের প্রশ্নের জবাবে হুমায়ুন কবির বলেন, শেখ হাসিনা ও ভারতে পালিয়ে যাওয়া অন্যান্য অপরাধীকে ফিরিয়ে আনা নিয়মিত প্রক্রিয়ার অংশ। ভারতের সঙ্গে বাংলাদেশের প্রত্যর্পণ চুক্তি রয়েছে এবং দেশে তাদের বিষয়ে বিচারিক কার্যক্রম চলমান। এটি দেশের মানুষের দীর্ঘদিনের প্রত্যাশা ও স্বাভাবিক দাবি।\r\n\r\nভারত সফর প্রসঙ্গে তিনি বলেন, ভারতের সঙ্গে আলোচনা ও কূটনৈতিক যোগাযোগ অব্যাহত রয়েছে। তবে সফরের বিষয়ে কোনো তাড়াহুড়ো নেই। শীর্ষ পর্যায়ের যেকোনো বৈঠকের জন্য পূর্বপ্রস্তুতির প্রয়োজন হয়। সঠিক সময়ে এবং আলোচনার অগ্রগতির ভিত্তিতে সফর অনুষ্ঠিত হবে।\r\n\r\nদ্বিপক্ষীয় সম্পর্কের বিষয়ে পররাষ্ট্র প্রতিমন্ত্রী বলেন, দেশের মানুষের অনুভূতি ও জাতীয় স্বার্থ বিসর্জন দিয়ে কারো সঙ্গে কোনো আপস করা হবে না। প্রতিবেশী ভারতের সঙ্গে সুসম্পর্ক বজায় রাখার জন্য কাজ চলছে। ভারতও বাংলাদেশের মানুষের এ অনুভূতি অনুধাবন করতে পেরেছে বলে উল্লেখ করেন তিনি।\r\n\r\nতিনি আরো বলেন, বিশাল জনসমর্থন নিয়ে গঠিত এ সরকার সফট পাওয়ার, প্রভাব ও মধ্যস্থতার ক্ষেত্রে বিশ্বমঞ্চে বাংলাদেশকে একটি গুরুত্বপূর্ণ দেশ হিসেবে গড়ে তুলতে প্রতিশ্রুতিবদ্ধ।', NULL, NULL, 'articles/jsIKpcNfTOGVMayr4Fo7BfUiKRFtqrRsPWvHW58L.jpg', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 0, 0, 25, '2026-08-22 05:11:23', '2026-08-22 05:11:23', '2026-08-25 02:25:49', NULL),
	(16, 'কলকাতার অগ্নিকাণ্ডে নিহত ৫ বাংলাদেশীর মরদেহ পেট্রাপোলে পৌঁছেছে', 'কলকতর-অগনকণড-নহত-৫-বলদশর-মরদহ-পটরপল-পছছ', NULL, 'নিহত ব্যক্তিদের মধ্যে কুষ্টিয়া সদরের প্রবীণ সাংবাদিক দেবাশীষ দত্ত, তার স্ত্রী আফসানা শারমীন, তিন বছরের ছেলে স্বর্ণাশীষ দত্ত ও শ্বশুর আকরাম আলী রয়েছেন।', 'ভারতের কলকাতায় একটি হোটেলে ভয়াবহ আগুনে পুড়ে মারা যাওয়া সাতজন বাংলাদেশীর মধ্যে পাঁচজনের মরদেহ ভারতের পেট্রাপোল সীমান্তে এসে পৌঁছেছে। আজ শনিবার বিকাল সাড়ে ৪টায় তিনটি অ্যাম্বুলেন্সে করে কলকাতার বাংলাদেশ মিশন থেকে মরদেহগুলো সীমান্তে পৌঁছায়। দুই দেশের কূটনৈতিক আনুষ্ঠানিকতা শেষে বিকেল সাড়ে ৫টার দিকে বেনাপোল সীমান্তের শূন্যরেখায় স্বজনদের কাছে মরদেহ হস্তান্তরের কথা রয়েছে।\r\n\r\nগত ১৯ আগস্ট ভোরে কলকাতার নিউমার্কেট এলাকার মির্জা গালিব স্ট্রিটের একটি আবাসিক হোটেলে আগুন লেগে মোট নয়জনের মৃত্যু হয়। তাদের মধ্যে সাতজন ছিলেন বাংলাদেশী নাগরিক। মৃতদেহের সুরতহাল ও ময়নাতদন্ত সম্পন্ন হওয়ার পর আইনি প্রক্রিয়া শেষে মরদেহ দেশে পাঠানো হচ্ছে।\r\n\r\nনিহত জোবায়ের বাবুর মেজো ভাই মনির হোসেন জানান, ব্যবসায়ের কাজে জোবায়ের সোমবার রাতে কলকাতায় যান। সেখান থেকে পরিবারের সঙ্গে কথা হলেও অগ্নিকাণ্ডের পর থেকে আর যোগাযোগ করা যায়নি। পরবর্তীতে বুধবার দুপুরে ভারতীয় দূতাবাস থেকে ফোনে স্বজনদের তার মৃত্যুর খবর জানানো হয় এবং ছবি পাঠিয়ে পরিচয় নিশ্চিত করা হয়।\r\n\r\nঅন্যদিকে নিহত সাংবাদিক দেবাশীষের স্বজনেরা বেনাপোল বন্দরে অপেক্ষা করছেন। পারিবারিক সূত্রে জানা গেছে, দেবাশীষ ও তার ছেলের শেষকৃত্য হিন্দু ধর্মীয় রীতিতে এবং স্ত্রী আফসানা ও শ্বশুরের দাফন ইসলামিক নিয়মে সম্পন্ন হবে। নয় বছর আগে ভালোবাসার টানে ধর্মীয় ভিন্নতা সত্ত্বেও তাদের বিয়ে হয়েছিল। দুর্ঘটনায় তাদের ১০ বছর বয়সী এক কন্যাসন্তান বেঁচে রইল।', NULL, NULL, 'articles/d6Ol9GXC0OZwDzCFtfP52B7yL5fgD2StIXhLXgfR.jpg', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 0, 0, 39, '2026-08-22 06:16:14', '2026-08-22 06:16:14', '2026-08-24 09:16:38', NULL),
	(17, 'অস্ট্রেলিয়ায় স্তন্যপায়ী প্রাণীর শরীরে প্রথমবার এইচ৫এন১ বার্ড ফ্লু শনাক্ত', 'অসটরলযয়-সতনযপয-পরণর-শরর-পরথমবর-এইচ৫এন১-বরড-ফল-শনকত', 'বার্ড ফ্লু শনাক্ত', 'দক্ষিণ অস্ট্রেলিয়ার পানিতে আনুমানিক এক লাখ ফার সিল রয়েছে। রাজ্যটির প্রধান ভেটেরিনারি কর্মকর্তা স্কাই ফ্রুয়ান বলেন, উপকূলের পাথুরে এলাকায় বন্য পাখির খুব কাছাকাছি বসবাস করায় সিলগুলো এ ভাইরাসে আক্রান্ত হওয়ার উচ্চঝুঁকিতে রয়েছে।', 'অস্ট্রেলিয়ায় প্রথমবারের মতো একটি স্তন্যপায়ী প্রাণীর শরীরে এইচ৫এন১ বার্ড ফ্লু ভাইরাসের সংক্রমণ শনাক্ত হয়েছে। দেশটির দক্ষিণ অস্ট্রেলিয়া অঙ্গরাজ্যের বিচপোর্ট উপকূলে একটি লং-নোজড ফার সিলের শরীরে প্রাণঘাতী এ ভাইরাসের উপস্থিতি নিশ্চিত করা হয়েছে। খবর রয়টার্স।\r\n\r\nঅস্ট্রেলিয়ায় জুনে এইচ৫এন১ ভাইরাস শনাক্ত হওয়ার পর থেকেই উচ্চমাত্রার সংক্রামক বার্ড ফ্লুর বিস্তার নিয়ে উদ্বেগ বাড়ছে। চলতি মাসে দেশটিতে প্রথমবারের মতো বিপুলসংখ্যক সামুদ্রিক পাখি মারা যাওয়ার ঘটনাও রেকর্ড করা হয়। পরিযায়ী সামুদ্রিক পাখির শরীরে প্রথম শনাক্ত হওয়ার পর ভাইরাসটি ধীরে ধীরে দেশটির বিভিন্ন বন্যপ্রাণীর মধ্যে ছড়িয়ে পড়ছে।\r\n\r\nদক্ষিণ অস্ট্রেলিয়ার কর্তৃপক্ষ জানিয়েছে, রাজ্যের রাজধানী অ্যাডিলেড থেকে প্রায় ৩১০ কিলোমিটার দক্ষিণে বিচপোর্ট উপকূলে সিলটির মৃতদেহ পাওয়া যায়। প্রাণীটির শরীরে কোনো আঘাতের চিহ্ন ছিল না।\r\n\r\nফেডারেল কৃষিমন্ত্রী জুলি কলিন্স বলেন, সিলটির মৃত্যু অন্য কোনো অসুস্থ বা মৃত সামুদ্রিক স্তন্যপায়ী প্রাণীর সঙ্গে সম্পর্কিত বলে মনে হচ্ছে না। তবে প্রাকৃতিক পরিবেশে এইচ৫এন১ ছড়িয়ে পড়লে ব্যাপক প্রাণহানি এড়ানো কঠিন।\r\n\r\nদক্ষিণ অস্ট্রেলিয়ার পানিতে আনুমানিক এক লাখ ফার সিল রয়েছে। রাজ্যটির প্রধান ভেটেরিনারি কর্মকর্তা স্কাই ফ্রুয়ান বলেন, উপকূলের পাথুরে এলাকায় বন্য পাখির খুব কাছাকাছি বসবাস করায় সিলগুলো এ ভাইরাসে আক্রান্ত হওয়ার উচ্চঝুঁকিতে রয়েছে।\r\n\r\nতিনি বলেন, বন্য পাখির সংস্পর্শে থাকার কারণে সিলগুলো তাদের পরিবেশে ভাইরাসের উচ্চমাত্রার উপস্থিতির মুখোমুখি হতে পারে।\r\n\r\nঅস্ট্রেলিয়ায় এর আগে পোলট্রি বা কৃষি খাতে এইচ৫এন১ শনাক্ত হয়নি। দেশটির ফেডারেল সরকার জানিয়েছে, শুক্রবার পর্যন্ত দেশজুড়ে বার্ড ফ্লুর ২৯৭টি সংক্রমণ শনাক্ত হয়েছে।\r\n\r\nবিশ্বজুড়ে বন্য পাখি থেকে বিভিন্ন স্তন্যপায়ী প্রাণীর মধ্যে এইচ৫এন১ ছড়িয়ে পড়ার ঘটনা বিজ্ঞানীদের উদ্বেগ বাড়িয়েছে। বিশেষ করে ভাইরাসটি নতুন প্রাণী প্রজাতিতে অভিযোজিত হচ্ছে কি না, তা নিবিড়ভাবে পর্যবেক্ষণ করছেন বিশেষজ্ঞরা।', NULL, NULL, 'articles/ENATL3jwr8WVKvztFiLADGKQ2aDYk7HmFGoKSbix.jpg', NULL, NULL, NULL, NULL, 18, 43, 1, NULL, 'published', 0, 0, 4, '2026-08-23 06:16:40', '2026-08-23 06:16:40', '2026-08-25 03:18:40', NULL),
	(18, 'ফিলিস্তিন ইস্যুতে ইসরায়েলের বিরুদ্ধে নিষেধাজ্ঞার আহ্বান সাবেক ১০২ কূটনীতিকের', 'ফলসতন-ইসযত-ইসরয়লর-বরদধ-নষধজঞর-আহবন-সবক-১০২-কটনতকর', 'ফিলিস্তিন ইস্যুতে', 'এক খোলা চিঠিতে তারা অস্ত্র সরবরাহ বন্ধ, বাণিজ্য চুক্তি স্থগিত এবং অধিকৃত ফিলিস্তিনি ভূখণ্ডে ইসরায়েলি বসতি সম্প্রসারণের বিরুদ্ধে কার্যকর ব্যবস্থা গ্রহণের দাবি জানিয়েছেন', 'ফিলিস্তিন ইস্যুতে আন্তর্জাতিক আইন রক্ষায় ইসরায়েলের বিরুদ্ধে যৌথভাবে কঠোর পদক্ষেপ নিতে ফ্রান্স ও যুক্তরাজ্যের প্রতি আহ্বান জানিয়েছেন দুই দেশের ১০২ জন সাবেক কূটনীতিক। এক খোলা চিঠিতে তারা অস্ত্র সরবরাহ বন্ধ, বাণিজ্য চুক্তি স্থগিত এবং অধিকৃত ফিলিস্তিনি ভূখণ্ডে ইসরায়েলি বসতি সম্প্রসারণের বিরুদ্ধে কার্যকর ব্যবস্থা গ্রহণের দাবি জানিয়েছেন।\r\n\r\nফরাসি সংবাদমাধ্যম লে মোঁদ-এ গতকাল প্রকাশিত ওই চিঠিতে বলা হয়, ফ্রান্স ও যুক্তরাজ্যকে একসঙ্গে কাজ করে ফিলিস্তিনে আন্তর্জাতিক আইন সমুন্নত রাখতে হবে। একইসঙ্গে ইসরায়েলি ও ফিলিস্তিনিদের জন্য সমান অধিকার নিশ্চিত করার আহ্বানও জানানো হয়।\r\n\r\nচিঠিতে স্বাক্ষরকারীদের মধ্যে রয়েছেন জাতিসংঘে যুক্তরাজ্যের সাবেক রাষ্ট্রদূত জেরেমি গ্রিনস্টক ও এমির জোনস প্যারি এবং ফ্রান্সের মধ্যপ্রাচ্যবিষয়ক সাবেক পরিচালক ইভ ওবাঁ দ্য লা মেসুজিয়ের ও দনি বোশার। মধ্যপ্রাচ্যে দীর্ঘ কূটনৈতিক অভিজ্ঞতার ভিত্তিতে তারা সতর্ক করে\r\n\r\nেন যে, অধিকৃত ফিলিস্তিনি ভূখণ্ডে ইসরায়েলের বর্তমান নীতি ভবিষ্যতে স্বাধীন ফিলিস্তিন রাষ্ট্র প্রতিষ্ঠার সম্ভাবনাকে স্থায়ীভাবে ধ্বংস করে দিতে পারে।\r\n\r\nচিঠিতে বলা হয়, ফিলিস্তিনিদের বাড়িঘর ধ্বংস এবং পশ্চিম তীরে বসতি স্থাপনকারীদের সহিংসতা কার্যত জাতিগত নিধনের শামিল। এসব কর্মকাণ্ডে ইসরায়েলি সেনাবাহিনী ও পুলিশের নীরব সমর্থন রয়েছে বলেও অভিযোগ করা হয়েছে।\r\n\r\nবিবৃতিতে স্বাক্ষরকারী যুক্তরাজ্যের সাবেক রাষ্ট্রদূত নিকোলাস হপটন আল জাজিরাকে বলেন, এসব শব্দচয়ন কূটনীতিকদের নিজস্ব নয়; বরং জাতিসংঘ ও আন্তর্জাতিক আইনি সংস্থাগুলোর মূল্যায়নের প্রতিফলন।\r\n\r\nলিবিয়ায় যুক্তরাজ্যের সাবেক রাষ্ট্রদূত পিটার মিলেট বলেন, শুধু নিন্দা বা উদ্বেগ প্রকাশের সময় শেষ। এখন প্রয়োজন বাস্তব পদক্ষেপ।\r\n\r\nচিঠিতে উল্লেখ করা হয়, ২০২৫ সালে ফ্রান্স ও যুক্তরাজ্য ফিলিস্তিন রাষ্ট্রকে স্বীকৃতি দিয়েছে। এখন সেই স্বীকৃতিকে অর্থবহ করতে জরুরি পদক্ষেপ প্রয়োজন। প্রথম বিশ্বযুদ্ধ-পরবর্তী সময়ে ফিলিস্তিন, সিরিয়া ও লেবাননে ফ্রান্স ও যুক্তরাজ্যের ঐতিহাসিক ভূমিকার কথাও স্মরণ করিয়ে দেয়া হয়েছে।\r\n\r\nএছাড়া জাতিসংঘের সংস্থাগুলোর মাধ্যমে গাজায় মানবিক সহায়তা পৌঁছানো, সাংবাদিক, কূটনীতিক ও সংসদ সদস্যদের নিরাপদ প্রবেশাধিকার নিশ্চিত করার দাবিও জানানো হয়েছে।\r\n\r\nতবে চিঠিতে শুধু ইসরায়েল নয়, ফিলিস্তিনি নেতৃত্বের সমালোচনাও করা হয়েছে। তাদের ‘অকার্যকর ও প্রতিনিধিত্বহীন’ উল্লেখ করে গণতান্ত্রিক ও জবাবদিহিমূলক রাষ্ট্র গঠনের ওপর গুরুত্ব দেয়া হয়েছে।\r\n\r\nকূটনীতিকদের ভাষ্য, কেবল বিবৃতি নয়, বাস্তব পদক্ষেপই এখন মধ্যপ্রাচ্যে দীর্ঘস্থায়ী শান্তির সম্ভাবনা টিকিয়ে রাখতে পারে।', NULL, NULL, 'articles/5be3uXcxOiBnKmfxJ3TowZ7gHMQ8pUGkDvWIyDMy.jpg', NULL, NULL, NULL, NULL, 18, 22, 1, NULL, 'published', 0, 0, 1, '2026-08-23 06:21:00', '2026-08-23 06:21:00', '2026-08-23 07:33:39', NULL),
	(19, 'পানি নিরাপত্তায় বিলিয়ন ডলার ঢালছে উপসাগরীয় দেশগুলো', 'পন-নরপততয়-বলয়ন-ডলর-ঢলছ-উপসগরয়-দশগল', 'এআই ও শিল্পায়নের বাড়তি চাহিদা', 'তেলনির্ভর অর্থনীতি থেকে বেরিয়ে নতুন অর্থনৈতিক কাঠামো গড়ার চেষ্টা করছে উপসাগরীয় দেশগুলো। শিল্প খাত সম্প্রসারণের পাশাপাশি কৃত্রিম বুদ্ধিমত্তা (এআই) ডেটা সেন্টার ও নতুন প্রযুক্তিতে বড় বিনিয়োগ করছে এসব দেশ।', 'শত শত কোটি ডলার ব্যয়ের পরিকল্পনা রয়েছে খাতটিতে। তবে এসব উচ্চপ্রযুক্তির প্রকল্প বাস্তবায়নে একটি মৌলিক সম্পদ এখন বড় বাধা হয়ে উঠছে। সেটি হলো পানি। খবর দ্য ন্যাশনাল।\r\n\r\nউপসাগরীয় দেশগুলো মধ্যপ্রাচ্যের অন্যতম পানি-সংকটাপন্ন অঞ্চল। সেখানে একদিকে জনসংখ্যা বাড়ছে, অন্যদিকে বাড়ছে শিল্প ও প্রযুক্তি খাতের পানির চাহিদা। ফলে এআই ও শিল্পায়নের উচ্চাভিলাষী পরিকল্পনা বাস্তবায়নে পানির নিরাপদ ও নিরবচ্ছিন্ন সরবরাহ নিশ্চিত করতে বড় বিনিয়োগ করছে উপসাগরীয় দেশগুলো।\r\n\r\nএ দৌড়ে এগিয়ে আছে সংযুক্ত আরব আমিরাত (ইউএই)। আরব বিশ্বের দ্বিতীয় বৃহত্তম অর্থনীতির দেশটি এআই অবকাঠামো তৈরিতে বড় বিনিয়োগ করছে। আবুধাবিতে তৈরি হচ্ছে ‘স্টারগেট ইউএই’। এটি ১ গিগাওয়াট ক্ষমতার একটি বড় এআই সুপারকম্পিউটিং ও ডেটা সেন্টার প্রকল্প। এতে ব্যয় হতে পারে ৩ হাজার কোটি ডলারের বেশি। ২০২৪-২৫ সালে ইউএইতে এআই-সংশ্লিষ্ট বিনিয়োগের পরিমাণ ৫৪৩ বিলিয়ন দিরহাম বা ১৪ হাজার ৭৯০ কোটি ডলার ছাড়িয়েছে। মাইক্রোসফট ও কেকেআরের মতো বৈশ্বিক প্রতিষ্ঠানও দেশটিতে বড় বিনিয়োগের ঘোষণা দিয়েছে।\r\n\r\nএআইয়ের জন্য প্রয়োজন বিশাল কম্পিউটিং সক্ষমতা। ডেটা সেন্টারে হাজার হাজার প্রসেসর ও গ্র্যাফিকস প্রসেসিং চিপ একসঙ্গে কাজ করে। এসব যন্ত্র প্রচুর তাপ উৎপন্ন করে। অতিরিক্ত তাপ নিয়ন্ত্রণে রাখতে প্রয়োজন হয় শীতলীকরণ ব্যবস্থা। এ কাজে গুরুত্বপূর্ণ ভূমিকা রাখে পানি।\r\n\r\nব্রুকিংসের তথ্য অনুযায়ী, একটি সাধারণ ডেটা সেন্টার প্রতিদিন প্রায় তিন লাখ গ্যালন পানি ব্যবহার করতে পারে। এ পরিমাণ পানি প্রায় এক হাজার পরিবারের দৈনিক চাহিদার সমান। বড় ডেটা সেন্টারে পানির ব্যবহার আরো বেশি। এসব কেন্দ্রে প্রতিদিন প্রায় ৫০ লাখ গ্যালন পর্যন্ত পানি লাগতে পারে, যা সর্বোচ্চ ৫০ হাজার মানুষের একটি শহরের দৈনিক পানির চাহিদার সমান।\r\n\r\nঅর্থাৎ এআই অবকাঠামোর বিস্তার শুধু বিদ্যুৎ ও চিপের চাহিদা বৃদ্ধি করছে না। একই সঙ্গে বাড়াচ্ছে পানির প্রয়োজন। মরুভূমিপ্রধান উপসাগরীয় দেশগুলোর জন্য এটি বড় বিষয়।\r\n\r\nপানির সংকট মোকাবেলায় ইউএইর প্রধান ভরসা সমুদ্রের পানি পরিশোধন বা ডিস্যালিনেশন। দেশটির আবুধাবি জ্বালানি বিভাগের নিয়ন্ত্রকবিষয়ক মহাপরিচালক আবদুলআজিজ আল ওবাইদলি বলেন, ‘গত ৫০ বছর ডিস্যালিনেশন প্লান্টের মাধ্যমে নিরাপদ পানির নির্ভরযোগ্য উৎস তৈরি হয়েছে।’\r\n\r\nএদিকে ইরান যুদ্ধের পর উপসাগরের সামুদ্রিক পরিবেশ নিয়ে উদ্বেগ আরো বেড়েছে। ক্ষেপণাস্ত্র, ড্রোন, অগ্নিকাণ্ড ও তেল দূষণের মতো ঘটনা সমুদ্রের বাস্তুতন্ত্রের জন্য বড় ঝুঁকি তৈরি করতে পারে। মার্চে বাহরাইন ও কুয়েতের ডিস্যালিনেশন প্লান্টে হামলার ঘটনাও এ অঞ্চলের পানি নিরাপত্তার বিষয়টি সামনে নিয়ে আসে।\r\n\r\nওয়ার্ল্ড রিসোর্সেস ইনস্টিটিউটের (ডব্লিউআরআই) অ্যাকুয়েডাক্ট ওয়াটার রিস্ক অ্যাটলাস অনুযায়ী, উপসাগরীয় দেশগুলো বিশ্বের সবচেয়ে বেশি পানি-চাপের মধ্যে থাকা দেশগুলোর মধ্যে রয়েছে। বিশ্বের নবায়নযোগ্য মিঠা পানির মাত্র ২ শতাংশ রয়েছে মধ্যপ্রাচ্যে। অঞ্চলটির ৮৩ শতাংশ এলাকা তীব্র পানিসংকটে রয়েছে। ২০৫০ সালের মধ্যে অঞ্চলটির পুরো জনগোষ্ঠী তীব্র পানিসংকটের মুখে পড়তে পারে বলে আশঙ্কা করছে ওয়ার্ল্ড রিসোর্সেস ইনস্টিটিউট।\r\n\r\nপানির চাহিদা সামলাতে উপসাগরীয় দেশগুলো এরই মধ্যে বড় বিনিয়োগ করছে। ন্যাচার জার্নালে প্রকাশিত তথ্য অনুযায়ী, ২০০৬-২৪ সাল পর্যন্ত মধ্যপ্রাচ্যে ডিস্যালিনেশন সক্ষমতা বাড়াতে ৫ হাজার ৩৪০ কোটি ডলার ব্যয় হয়েছে। এটি বিশ্বে এ খাতে মোট মূলধনি ব্যয়ের প্রায় ৪৭ দশমিক ৫ শতাংশ।\r\n\r\n২০২৮ সাল পর্যন্ত অঞ্চলে আরো ২ হাজার ৬০০ কোটি ডলার বিনিয়োগের প্রত্যাশা রয়েছে। আগামী দুই বছরে দৈনিক ডিস্যালিনেশন সক্ষমতা ৪ কোটি ১০ লাখ ঘনমিটারে পৌঁছতে পারে।\r\n\r\nউপসাগরীয় দেশগুলোর পানির নিরাপত্তা ডিস্যালিনেশনের ওপর ব্যাপকভাবে নির্ভরশীল। ইউএইতে মোট পানির চাহিদার প্রায় ৪০ শতাংশ ডিস্যালিনেশন থেকে আসে। কুয়েত ও ওমানে এ নির্ভরতা প্রায় ৯০ শতাংশ।\r\n\r\nউপসাগরীয় অঞ্চলের সবচেয়ে বড় অর্থনীতি সৌদি আরবও তেলনির্ভরতা কমাতে বড় পরিবর্তনের পথে রয়েছে। অবকাঠামো, আবাসন ও শিল্প প্রকল্পে বিলিয়ন বিলিয়ন ডলার বিনিয়োগ করছে দেশটি। পাশাপাশি এআই খাতেও বড় পরিকল্পনা রয়েছে।\r\n\r\nকাতারও এআই অবকাঠামোয় বিনিয়োগ বাড়াচ্ছে। কিউএআই নামে একটি প্রতিষ্ঠান গঠন করেছে দেশটি। এটি কাতার ও বিদেশে এআই অবকাঠামোয় বিনিয়োগ, উন্নয়ন ও ব্যবস্থাপনার কাজ করবে।\r\n\r\nএআই অবকাঠামো যত বাড়বে, পানির চাহিদাও তত বাড়বে। একটি যৌথ গবেষণা প্রতিবেদনের হিসাবে, শুধু ইউএইর এআই খাতেই ২০৩০ সাল নাগাদ বছরে প্রায় ৬ হাজার ১০০ কোটি লিটার পানির প্রয়োজন হতে পারে। একই সময় সৌদি আরবে ডেটা সেন্টারের বিদ্যুতের চাহিদা বছরে ২৯ শতাংশ হারে বাড়তে পারে।\r\n\r\nপানির ব্যবহার কমাতে উপসাগরীয় দেশগুলোর বিভিন্ন কোম্পানি নতুন প্রযুক্তি ব্যবহার শুরু করেছে। আবুধাবির খাজনা ও সৌদি আরবের ডেটাভোল্ট ও আলফানারের মতো কোম্পানি তরলভিত্তিক শীতলীকরণসহ বিভিন্ন উচ্চ দক্ষতার প্রযুক্তি পরীক্ষা বা ব্যবহার করছে।', NULL, NULL, 'articles/biPWy6D9rx79DQZLUTt1dYyIgVKyHfL4RKjBaGdP.jpg', NULL, NULL, NULL, NULL, 18, 22, 1, NULL, 'published', 0, 0, 1, '2026-08-23 06:25:31', '2026-08-23 06:25:31', '2026-08-23 07:36:17', NULL),
	(20, 'বিটকয়েনের দাম ৭৫ হাজার ডলার ছাড়াল', 'বটকযনর-দম-৭৫-হজর-ডলর-ছড়ল', 'ফের চাঙ্গা ক্রিপ্টো বাজার', 'এশিয়ার বাজারে ভার্চুয়াল মুদ্রা বিটকয়েনের দামে বড় ধরনের ঊর্ধ্বমুখী প্রবণতা দেখা গেছে। গত বৃহস্পতিবার লেনদেনের শুরুতেই শীর্ষ এ ক্রিপ্টোকারেন্সির দাম ৪ শতাংশের বেশি বৃদ্ধি পায়।', 'এতে বিটকয়েনের দর ৭৫ হাজার ডলারের গণ্ডি পার হয়। খবর দ্য ন্যাশনাল।\r\n\r\nযুক্তরাষ্ট্রের ট্রেজারি বিভাগের নতুন ঘোষণা ও দেশটির প্রেসিডেন্ট ডোনাল্ড ট্রাম্পের ক্রিপ্টো-নীতিসংক্রান্ত সাম্প্রতিক আশ্বাসের পর থেকেই বাজারে গতি ফিরেছে। উল্লেখ্য, জুলাইয়ের মাঝামাঝিতে বিশ্ববাজারে ভূরাজনৈতিক অস্থিরতার কারণে বিটকয়েনের দরপতন হয়। ওই সময় ক্রিপ্টোকারেন্সির শীর্ষ টোকেনটির দাম প্রায় ২ শতাংশ কমে ৬২ হাজার ৮০০ ডলারে নামে।\r\n\r\nইউএই সময় সকাল ৮টা ২৮ মিনিটে বিটকয়েন সর্বোচ্চ ৭৫ হাজার ৭৪০ ডলারে পৌঁছে। তবে কিছুটা সংশোধন হয়ে পরবর্তী সময়ে তা ৭৪ হাজার ৮০৬ ডলারে নেমে আসে। ক্রিপ্টো এক্সচেঞ্জ কয়েনবেজের তথ্য অনুযায়ী, গত ২৪ ঘণ্টায় বিটকয়েনের দাম প্রায় ৮ শতাংশ বেড়েছে। চলতি সপ্তাহে সব মিলিয়ে এর দর বেড়েছে প্রায় ২০ শতাংশ।\r\n\r\nবাজার বিশ্লেষকরা বলছেন, মার্কিন ট্রেজারি সেক্রেটারি স্কট বেসেন্ট বন্ড বাইব্যাকের পরিমাণ দ্বিগুণ করার সিদ্ধান্ত জানানোর পর থেকেই বিনিয়োগকারীদের মাঝে নতুন উৎসাহ তৈরি হয়। পাশাপাশি ক্রিপ্টো খাতের শীর্ষ নির্বাহীদের সঙ্গে প্রেসিডেন্ট ট্রাম্পের সাম্প্রতিক বৈঠক বাজারকে আরো চাঙ্গা করেছে।\r\n\r\nপ্রেসিডেন্ট ট্রাম্প দীর্ঘদিন ধরে ক্রিপ্টোকারেন্সির পক্ষে অবস্থান নিচ্ছেন। নির্বাচনী প্রচারে তিনি যুক্তরাষ্ট্রকে ‘বিশ্বের ক্রিপ্টো রাজধানী’ হিসেবে গড়ে তোলার প্রতিশ্রুতি দিয়েছিলেন। সম্প্রতি তিনি মার্কিন সিনেটকে ‘ক্লিয়ারিটি অ্যাক্ট’ নামে একটি ক্রিপ্টো-নীতিসংক্রান্ত বিল পাসের আহ্বান জানান। তিনি একটি সুষ্ঠু আইনের মাধ্যমে ক্রিপ্টো বাজারের দ্রুত বিকাশ নিশ্চিত করতে চান।\r\n\r\nবিটগেট রিসার্চের প্রধান বিশ্লেষক রায়ান লি জানান, মার্কিন সরকারের নীতিগত এ পদক্ষেপের প্রভাব অনেক দূরপ্রসারী হবে। এটি কেবল বিটকয়েনের দাম বাড়াবে না, বরং অন্যান্য উদীয়মান দেশের নিয়ন্ত্রকদের জন্যও ডিজিটাল অ্যাসেটের আইন তৈরির একটি নতুন কাঠামো নির্ধারণ করবে।', NULL, NULL, 'articles/5hjTWqSc15rvKrKlMJ8LiO6H9lcUSuJcSSqK5wkr.jpg', NULL, NULL, NULL, NULL, 18, NULL, 1, NULL, 'published', 0, 0, 1, '2026-08-23 06:31:09', '2026-08-23 06:31:09', '2026-08-23 06:41:23', NULL),
	(21, 'চীনের বাজারে কেন পিছিয়ে পড়ছে যুক্তরাষ্ট্রের বড় ব্র্যান্ড', 'চনর-বজর-কন-পছয়-পড়ছ-যকতরষটরর-বড়-বরযনড', NULL, 'একসময় চীন ছিল মার্কিন ব্র্যান্ডগুলোর জন্য সবচেয়ে আকর্ষণীয় বাজারগুলোর একটি।', '১৪০ কোটির বেশি মানুষের বিশাল বাজার ও দ্রুত বাড়তে থাকা ভোক্তা ব্যয়কে লক্ষ্য করে চীনে ব্যবসা বাড়াতে প্রতিযোগিতায় নামে বিশ্বের বড় সব মার্কিন কোম্পানি।\r\n\r\nকিন্তু বিভিন্ন আন্তর্জাতিক প্রতিবেদন বলছে, সে চিত্র এখন বদলে গেছে। নাইকি, স্টারবাকস ও জেনারেল মোটরসের মতো বড় মার্কিন ব্র্যান্ড চীনের বাজারে আগের অবস্থান ধরে রাখতে পারছে না। স্থানীয় ব্র্যান্ডের উত্থান, ভোক্তার চাহিদার পরিবর্তন ও যুক্তরাষ্ট্র-চীন ভূরাজনৈতিক উত্তেজনা ব্যবসায় চাপ তৈরি করেছে।\r\n\r\nচীনের বাজারে মার্কিন ব্র্যান্ডগুলোর পতনের বড় উদাহরণ নাইকি। ২০২১ সালের তুলনায় দেশটিতে কোম্পানিটির ব্যবসা ৩০ শতাংশ সংকোচন হয়েছে। চলতি বছরের বসন্তে চীনে নাইকির বার্ষিক আয় আট বছরের মধ্যে সর্বনিম্ন পর্যায়ে নেমেছে। চীনা ক্রেতাদের একটি বড় অংশ এখন স্থানীয় স্পোর্টসওয়্যার ব্র্যান্ডের দিকে ঝুঁকছে। বাজার গবেষণা প্রতিষ্ঠান অ্যাপারচার চায়নার প্রতিষ্ঠাতা ইয়ালিং জিয়াংয়ের মতে, চীনের বাজারে নাইকি অনেকটাই প্রাসঙ্গিকতা হারিয়েছে। গত এক দশকে চীনের স্পোর্টসওয়্যার বাজার দ্বিগুণের বেশি বাড়লেও সে সুযোগের পুরোটা নিতে পারেনি নাইকি।\r\n\r\nচীনে একই ধরনের চাপের মুখে পড়েছে স্টারবাকস। ১৯৯৯ সালে দেশটিতে প্রবেশের পর দ্রুত ব্যবসা সম্প্রসারণ করে কফি চেইনটি। ২০১৫ সালের মধ্যে চীন হয়ে ওঠে স্টারবাকসের দ্বিতীয় বৃহত্তম বাজার। কিন্তু কভিড-১৯ মহামারীর পর পরিস্থিতি বদলে যায়। চীনা ক্রেতাদের একটি অংশ কম দামের স্থানীয় কফি ব্র্যান্ডের দিকে ঝুঁকে পড়ে। এর মধ্যে সবচেয়ে বড় প্রতিদ্বন্দ্বী হয়ে উঠেছে লাকিন কফি। বর্তমানে চীনে লাকিনের দোকানের সংখ্যা স্টারবাকসের তুলনায় তিন গুণ।', NULL, NULL, 'articles/om9f5F8vdMM193MgZetUBP7EEsowHzieZtZCR9rS.jpg', NULL, NULL, NULL, NULL, 18, 21, 1, NULL, 'published', 0, 0, 1, '2026-08-23 06:34:44', '2026-08-23 06:34:44', '2026-08-23 07:36:02', NULL),
	(22, 'গাদ্দাফির পতনের ১৫ বছর পরও বিভক্তির বৃত্তে লিবিয়া', 'গদদফর-পতনর-১৫-বছর-পরও-বভকতর-বতত-লবয়', NULL, '২০১৪ সালে বিরোধ নতুন গৃহযুদ্ধে রূপ নেয়। এর মধ্য দিয়ে দেশটি পূর্ব ও পশ্চিম—দুটি প্রধান রাজনৈতিক ও সামরিক শিবিরে ভাগ হয়ে যায়।', '২০১১ সালের আগে আফ্রিকার অন্যতম সমৃদ্ধ দেশ হিসেবে পরিচিত ছিল লিবিয়া। বিপুল জ্বালানি তেল ও গ্যাসসম্পদ, তুলনামূলক উচ্চ মাথাপিছু আয় এবং শিক্ষা-স্বাস্থ্যসহ বিভিন্ন খাতে রাষ্ট্রীয় ভর্তুকির কারণে দেশটির নাগরিকরা উন্নত জীবনযাপন করতেন। কিন্তু মুয়াম্মার গাদ্দাফির পতনের পর সেই লিবিয়া আর ঘুরে দাঁড়াতে পারেনি। দেড় দশক ধরে রাজনৈতিক বিভাজন, গৃহযুদ্ধ, সশস্ত্র গোষ্ঠীর উত্থান, বিদেশী শক্তির হস্তক্ষেপ এবং তেলসম্পদের নিয়ন্ত্রণ নিয়ে সংঘাত দেশটির রাষ্ট্রীয় কাঠামোকে প্রায় অকার্যকর করে রেখেছে। গাদ্দাফিবিরোধী অভ্যুত্থানের ১৫ বছর পর এখন যুক্তরাষ্ট্র, তুরস্ক, মিসর ও কাতারসহ কয়েকটি দেশ আবার ‘এক লিবিয়া’ গঠনের চেষ্টা করছে। তবে এ উদ্যোগ দেশটিকে সত্যিকার অর্থে ঐক্যবদ্ধ করবে, নাকি নতুন করে ক্ষমতা ভাগাভাগির আরেকটি অস্থায়ী ব্যবস্থা তৈরি করবে—সে প্রশ্নের উত্তর এখনো স্পষ্ট নয়।\r\n\r\nমুয়াম্মার গাদ্দাফি ১৯৬৯ সালে এক সামরিক অভ্যুত্থানের মাধ্যমে রাজা ইদ্রিসকে উৎখাত করে ক্ষমতা দখল করেন। পরবর্তী ৪২ বছর তিনি লিবিয়া শাসন করেন। গাদ্দাফির শাসন ছিল কর্তৃত্ববাদী। দেশে কার্যকর বহুদলীয় রাজনীতি, স্বাধীন নির্বাচন কিংবা মতপ্রকাশের পর্যাপ্ত সুযোগ ছিল না। বিরোধী রাজনীতি কঠোরভাবে দমন করা হতো। রাজনৈতিক প্রতিপক্ষ, মানবাধিকারকর্মী ও সরকারের সমালোচকদের গ্রেফতার, নির্যাতন ও গুম করার অভিযোগও ছিল। তবে একই সঙ্গে জ্বালানি তেলের বিপুল আয় ব্যবহার করে শিক্ষা, স্বাস্থ্য, আবাসন, বিদ্যুৎ, জ্বালানি ও খাদ্যে বড় অঙ্কের রাষ্ট্রীয় ভর্তুকি দেয়া হতো।\r\n\r\nগাদ্দাফি আমলে লিবিয়ায় শিক্ষার প্রসার, নারীদের শিক্ষায় অংশগ্রহণ এবং সাক্ষরতার হারে উল্লেখযোগ্য উন্নতি হয়েছিল। জনগণের জন্য শিক্ষা ও স্বাস্থ্যসেবায় রাষ্ট্রের বড় ভূমিকা ছিল। জ্বালানি তেলের আয় ও কম জনসংখ্যার কারণে মাথাপিছু আয়ের দিক থেকে দেশটি আফ্রিকার শীর্ষ দেশগুলোর একটিতে পরিণত হয়। অবকাঠামো উন্নয়নেও বড় প্রকল্প নেয়া হয়েছিল। মরুভূমির নিচে থাকা ভূগর্ভস্থ পানি উত্তরের জনবসতিপূর্ণ এলাকায় পৌঁছে দিতে নির্মিত ‘গ্রেট ম্যান-মেড রিভার’ ছিল বিশ্বের অন্যতম বৃহৎ পানি সরবরাহ প্রকল্প।\r\n\r\nতবে এ সমৃদ্ধির ভিত ছিল দুর্বল। অর্থনীতি প্রায় পুরোপুরি তেলনির্ভর ছিল এবং শক্তিশালী বেসরকারি খাত গড়ে ওঠেনি। রাষ্ট্রীয় প্রতিষ্ঠানগুলোও ব্যক্তিকেন্দ্রিক শাসনের বাইরে স্বাধীনভাবে বিকশিত হতে পারেনি। সেনাবাহিনী, বিচারব্যবস্থা, প্রশাসন ও রাজনৈতিক প্রতিষ্ঠানকে এমনভাবে নিয়ন্ত্রণ করা হয়েছিল, যাতে কোনো বিকল্প ক্ষমতাকেন্দ্র তৈরি না হয়। ফলে গাদ্দাফির পতনের পর দেশ পরিচালনার মতো শক্তিশালী প্রতিষ্ঠান কিংবা সবার কাছে গ্রহণযোগ্য নেতৃত্ব অবশিষ্ট ছিল না।\r\n\r\n২০১১ সালের ফেব্রুয়ারিতে আরব বসন্তের প্রভাবে বেনগাজিতে গাদ্দাফিবিরোধী বিক্ষোভ শুরু হয়। নিরাপত্তা বাহিনীর সহিংসতার মুখে আন্দোলন দ্রুত সশস্ত্র বিদ্রোহে রূপ নেয়। পরিস্থিতি একপর্যায়ে গৃহযুদ্ধে গড়ায়। বেসামরিক নাগরিকদের সুরক্ষার যুক্তিতে জাতিসংঘ নিরাপত্তা পরিষদ লিবিয়ায় উড্ডয়ন নিষিদ্ধ এলাকা কার্যকরের অনুমোদন দেয়। এরপর যুক্তরাষ্ট্র, যুক্তরাজ্য ও ফ্রান্সের নেতৃত্বে ন্যাটো বাহিনী গাদ্দাফির সামরিক স্থাপনা ও বাহিনীর ওপর বিমান হামলা শুরু করে।', NULL, NULL, 'articles/pL9vQIWmPlu3meyKL3m6SdnYdc7xTSGfE9OVbS8w.jpg', NULL, NULL, NULL, NULL, 18, 25, 1, NULL, 'published', 0, 0, 4, '2026-08-23 07:45:27', '2026-08-23 07:45:27', '2026-08-26 06:54:42', NULL),
	(23, 'যুক্তরাষ্ট্রের পণ্যে পাল্টা শুল্ক বসানোর ঘোষণা কানাডার', 'যকতরষটরর-পণয-পলট-শলক-বসনর-ঘষণ-কনডর', 'আন্তর্জাতিক ব্যবসা ও অর্থনীতি', 'মার্ক কার্নি বলেন, ‘যুক্তরাষ্ট্রের ইস্পাত, দুগ্ধপণ্য, বৈদ্যুতিক সরঞ্জাম, কৃষি যন্ত্রপাতি, কাগজ ও ইলেকট্রনিকসসহ বিভিন্ন পণ্যে নতুন শুল্ক বসাবে কানাডা। আগামী ৮ সেপ্টেম্বর থেকে এসব শুল্ক কার্যকর হবে।’', 'যুক্তরাষ্ট্রের আরোপ করা ৫০ শতাংশ শুল্কের জবাবে পাল্টা শুল্কারোপের ঘোষণা দিয়েছে কানাডা। দেশটির প্রধানমন্ত্রী মার্ক কার্নি গতকাল অটোয়ায় এ ঘোষণা দেন। খবর আল জাজিরা।\r\n\r\nতিনি জানান, যুক্তরাষ্ট্র যেভাবে কানাডার পণ্যে নতুন শুল্ক আরোপ করেছে, কানাডাও একই পরিমাণ শুল্ক দিয়ে তার জবাব দেবে। এর মাধ্যমে কানাডার শ্রমিক, কৃষক, পরিবার ও ব্যবসাপ্রতিষ্ঠানকে সুরক্ষা দেয়ার চেষ্টা করা হবে।\r\n\r\nসম্প্রতি যুক্তরাষ্ট্রের প্রেসিডেন্ট ডোনাল্ড ট্রাম্প কানাডার প্রায় ২ হাজার কোটি ডলারের পণ্যে ৫০ শতাংশ শুল্ক আরোপ করেন। এসব পণ্যের মধ্যে রয়েছে অ্যালকোহল, আসবাব, দুগ্ধপণ্য, সিমেন্ট, পোশাক, মাছ ধরার সরঞ্জাম ও হকি খেলার সামগ্রী। নতুন শুল্কের আওতায় পড়া পণ্যের মূল্য যুক্তরাষ্ট্রে কানাডার রফতানির প্রায় ৫ দশমিক ৫ শতাংশ।\r\n\r\nকানাডার প্রধানমন্ত্রী জানান, যুক্তরাষ্ট্রের নতুন শুল্কের কারণে ক্ষতিগ্রস্ত শিল্পগুলোকে সরকার সহায়তা দেবে। আগামী সপ্তাহে এ সহায়তা কর্মসূচির ঘোষণা আসতে পারে।\r\n\r\nকার্নি বলেন, যুক্তরাষ্ট্রের সঙ্গে আলোচনার শুরুতে অগ্রগতি হয়েছিল। কিন্তু সাম্প্রতিক সময়ে ওয়াশিংটন নতুন কিছু শর্ত দেয়। কানাডার দৃষ্টিতে এসব শর্ত ছিল অর্থনৈতিকভাবে অযৌক্তিক ও অন্যায্য। একই সঙ্গে এসব শর্ত ভবিষ্যৎ বাণিজ্য চুক্তির সুবিধা নিয়েও অনিশ্চয়তা তৈরি করেছে।', NULL, NULL, 'articles/MHfH7JppA2HYUehLEIwzalrLZeZ5X8QS4eWKlJwP.jpg', NULL, NULL, NULL, NULL, 12, 13, 1, NULL, 'published', 0, 0, 1, '2026-08-23 07:51:48', '2026-08-23 07:51:48', '2026-08-23 07:51:58', NULL),
	(24, 'কার্যক্রম শুরু করেছে ইনভেস্ট বাংলাদেশ— বিনিয়োগকারীরা যেভাবে উপকৃত হবেন', 'করযকরম-শর-করছ-ইনভসট-বলদশ-বনয়গকরর-যভব-উপকত-হবন', NULL, 'বাংলাদেশ বিনিয়োগ উন্নয়ন কর্তৃপক্ষ (বিডা), বাংলাদেশ অর্থনৈতিক অঞ্চল কর্তৃপক্ষ (বেজা) এবং পাবলিক-প্রাইভেট পার্টনারশিপ কর্তৃপক্ষকে (পিপিপিএ) একীভূত করে সরকার ইনভেস্ট বাংলাদেশ গঠন করেছে।', 'ইনভেস্ট বাংলাদেশ আইন, ২০২৬-এর আওতায় গেজেট প্রকাশের পর প্রথম কর্মদিবসেই আজ কার্যক্রম শুরু করেছে ইনভেস্ট বাংলাদেশ।\r\n\r\nবাংলাদেশ বিনিয়োগ উন্নয়ন কর্তৃপক্ষ (বিডা), বাংলাদেশ অর্থনৈতিক অঞ্চল কর্তৃপক্ষ (বেজা) এবং পাবলিক-প্রাইভেট পার্টনারশিপ কর্তৃপক্ষকে (পিপিপিএ) একীভূত করে সরকার ইনভেস্ট বাংলাদেশ গঠন করেছে। প্রধানমন্ত্রীর কার্যালয়ের অধীন এ সংস্থা এখন দেশের শীর্ষ বিনিয়োগ উন্নয়ন সংস্থা।\r\n\r\nইনভেস্ট বাংলাদেশ আজ নতুন ব্র্যান্ড পরিচয়ও প্রকাশ করেছে। নতুন এই পরিচয় তিনটি প্রতিষ্ঠান থেকে একটি জাতীয় বিনিয়োগ প্লাটফর্মে রূপান্তরকে তুলে ধরে।\r\n\r\nনতুন কর্তৃপক্ষ বিনিয়োগ সহায়তা, নীতি সমন্বয়, অর্থনৈতিক অঞ্চল উন্নয়ন এবং সরকারি-বেসরকারি অংশীদারত্বের সক্ষমতাকে এক প্রতিষ্ঠানে এনেছে। ফলে দেশী-বিদেশী বিনিয়োগকারীরা সারা দেশের বিনিয়োগ সুযোগের জন্য এক জায়গা থেকে সহায়তা পাবেন। বিনিয়োগসেবা, সুবিধা ও নীতির বিষয়ে সরকারের সঙ্গে সহজ ও সমন্বিতভাবে কাজ করার জন্য বিনিয়োগকারী ও অংশীদারেরা দীর্ঘদিন ধরে এমন একটি একক যোগাযোগকেন্দ্র চেয়ে আসছিলেন।\r\n\r\nইনভেস্ট বাংলাদেশের চেয়ারম্যান আশিক চৌধুরী বলেন, ‘এটি শুধু তিনটি প্রতিষ্ঠানের একীভূতকরণ নয়। বিনিয়োগকারীকে কেন্দ্রে রেখে সরকারের কাজ আরো কার্যকরভাবে সাজানোই এর লক্ষ্য। আমাদের সক্ষমতাগুলো এক করে আমরা বিনিয়োগের পুরো পথে দায়িত্ব ও জবাবদিহি আরো স্পষ্ট এবং আরো সমন্বিত সহায়তা দিতে চাই। পূর্বসূরি প্রতিষ্ঠানগুলোর অর্জন ও অভিজ্ঞতার ওপর ভিত্তি করে আমরা আরো বড় ও শক্তিশালী দল হিসেবে নতুন অধ্যায় শুরু করব।’\r\n\r\nএক সংবাদ বিজ্ঞপ্তিতে বলা হয়েছে, ইনভেস্ট বাংলাদেশ আইন, ২০২৬ আরো সমন্বিত জাতীয় বিনিয়োগ ব্যবস্থার ভিত্তি তৈরি করেছে।\r\n\r\n- আইনটি অর্থনৈতিক অঞ্চল, মুক্ত বাণিজ্য অঞ্চল এবং ঘোষিত অন্যান্য শিল্পাঞ্চলকে একটি সমন্বিত কাঠামোর আওতায় আনার সুযোগ দিয়েছে;\r\n\r\n- লাইসেন্স, অনুমোদন ও সরকারি সেবার পদ্ধতি এবং সময়সীমা নির্ধারণের সুযোগ দিয়েছে;\r\n\r\n- সরকারি-বেসরকারি অংশীদারত্বের অনুমোদন কাঠামো আরো স্পষ্ট করার এবং ছোট পিপিপি প্রকল্পের অনুমোদন সহজ করার সুযোগ দিয়েছে;\r\n\r\n- অব্যবহৃত সরকারি জমি, স্থাপনা, শেয়ার ও স্বত্ব উৎপাদনশীল কাজে ব্যবহারের সুযোগ তৈরি করেছে; এবং\r\n\r\n- বিনিয়োগ ও ব্যবসাসংক্রান্ত সব সেবা একটি ডিজিটাল প্লাটফর্মে আনার ব্যবস্থা করেছে এ আইন।\r\n\r\nআরো বলা হচ্ছে, অনুমোদন প্রক্রিয়া এগিয়ে নেয়া, বিনিয়োগ-প্রস্তুত স্থান খুঁজে পাওয়া এবং ব্যবসার প্রবৃদ্ধির বাধা মোকাবেলায় ইনভেস্ট বাংলাদেশ বিনিয়োগকারীদের সহায়তা করবে ইনভেস্ট বাংলাদেশ। সংস্থাটি বাংলাবিজ পরিচালনা অব্যাহত রাখবে। বাংলাবিজ বাংলাদেশের বিনিয়োগসেবার একক ডিজিটাল প্লাটফর্ম। এর মাধ্যমে ব্যবসার লাইসেন্স ও অনুমতিপত্র অনলাইনে নির্ধারিত সময়ের মধ্যে পাওয়া যাবে।\r\n\r\nনতুন কর্তৃপক্ষ ১৪ দিনের ব্যবসায়িক লাইসেন্সিং কাঠামো কার্যকর করতে কাজ করছে। দ্রুত ও পূর্বানুমানযোগ্য ব্যবসা পরিবেশ গড়ার সরকারি অঙ্গীকার বাস্তবায়নে এটি একটি গুরুত্বপূর্ণ পদক্ষেপ। ১৮০ দিনের সময়সীমা এখন শেষের দিকে। মার্চে ঘোষণা করা অঙ্গীকারগুলোর বাস্তবায়ন অগ্রগতি নিয়ে সময়সীমা শেষ হওয়ার আগেই সংস্থাটি একটি প্রতিবেদন প্রকাশ করবে।\r\n\r\nবিনিয়োগকারীরা কীভাবে উপকৃত হবেন?\r\n\r\nবিনিয়োগকারীরা অনুমোদন, নিবন্ধন, আমদানি-রফতানি সেবা, প্রণোদনা, শিল্পাঞ্চল এবং অন্যান্য সরকারি সেবা আরো সহজে, দ্রুত ও সমন্বিতভাবে পাবেন। আইনটি লাইসেন্স, অনুমোদন ও সেবা দেয়ার পদ্ধতি এবং সময়সীমা নির্ধারণের সুযোগও দিয়েছে।\r\n\r\nআইনটি কী নতুন সুযোগ তৈরি করেছে?\r\n\r\nআইনটি অর্থনৈতিক অঞ্চল, মুক্ত বাণিজ্য অঞ্চল এবং ঘোষিত অন্যান্য শিল্পাঞ্চলকে একটি সমন্বিত কাঠামোর আওতায় আনার সুযোগ দিয়েছে। অব্যবহৃত সরকারি জমি, স্থাপনা, শেয়ার ও স্বত্ব উৎপাদনশীল কাজে ব্যবহার করা যাবে। একইসঙ্গে পিপিপি প্রকল্পের অনুমোদন কাঠামো আরো স্পষ্ট এবং ছোট প্রকল্পের অনুমোদন সহজ করার সুযোগ তৈরি হয়েছে।\r\n\r\nবর্তমান বিনিয়োগসেবাগুলোর কী হবে?\r\n\r\nবিদ্যমান বিনিয়োগসেবা ইনভেস্ট বাংলাদেশের অধীনে আগের মতোই চলবে। এ একীভূতকরণ শুধু প্রাতিষ্ঠানিক পর্যায়ে হয়েছে। এর লক্ষ্য বিনিয়োগকারীদের পথ সহজ করা, এক জায়গা থেকে সেবা দেয়া এবং পুরো বিনিয়োগ প্রক্রিয়ায় আরো সমন্বিত সহায়তা নিশ্চিত করা।\r\n\r\nবিনিয়োগসেবা কীভাবে ডিজিটাল করা হবে?\r\n\r\nআইনটি বিনিয়োগ ও ব্যবসাসংক্রান্ত সেবাগুলোকে একটি ডিজিটাল প্লাটফর্মে আনার সুযোগ দিয়েছে। এর ফলে সিঙ্গেল-উইন্ডো ক্লিয়ারেন্স, ওয়ান-স্টপ সেবা এবং ব্যবসার লাইসেন্স ও অনুমোদনের অনলাইন প্রক্রিয়া আরো এগিয়ে নেয়া যাবে।\r\n\r\nইনভেস্ট বাংলাদেশ কি অর্থনৈতিক অঞ্চলের ভেতরে ও বাইরে—দুই জায়গাতেই প্রকল্পে সহায়তা করবে?\r\n\r\nঅর্থনৈতিক অঞ্চল অগ্রাধিকার পাবে, কারণ সেখানে বিদ্যুৎ, গ্যাস, পানি এবং পরিবহন নেটওয়ার্কে সংযোগ আরো দ্রুত ও কার্যকরভাবে দেয়া যায়। তবে প্রকল্পের ধরন ও বিনিয়োগকারীর চাহিদা অনুযায়ী ইনভেস্ট বাংলাদেশ অর্থনৈতিক অঞ্চলের বাইরের প্রকল্পেও সহায়তা করবে। এ ক্ষেত্রে অব্যবহৃত সরকারি সম্পদ ব্যবহারের সুযোগও থাকবে।\r\n\r\nকর্মকর্তা-কর্মচারীদের কী হবে?\r\n\r\nবিডা, বেজা ও পিপিপিএর নিয়মিত কর্মকর্তা-কর্মচারীরা সমমানের পদে ইনভেস্ট বাংলাদেশে অন্তর্ভুক্ত হবেন। তাদের চাকরির ধারাবাহিকতা ও বর্তমান সুযোগ-সুবিধা বহাল থাকবে। পরামর্শক, আউটসোর্সিং কর্মী ও দৈনিক মজুরিভিত্তিক কর্মীরা তাদের বর্তমান চুক্তি বা আদেশের শর্ত অনুযায়ী কাজ চালিয়ে যাবেন।', NULL, NULL, 'articles/CcNckRZY9t4R8Z6OBLmpbvVktjZhoENPT8fvNpdY.jpg', NULL, NULL, NULL, NULL, 12, 13, 1, NULL, 'published', 0, 0, 1, '2026-08-23 08:02:58', '2026-08-23 08:02:58', '2026-08-23 08:03:09', NULL),
	(25, 'সাউথ এশিয়া ইনসিওরেন্সের মেরিন কার্গো বীমা দাবি পরিশোধ', 'সউথ-এশয়-ইনসওরনসর-মরন-করগ-বম-দব-পরশধ', NULL, NULL, 'মেরিন কার্গো বীমা দাবি পরিশোধ করেছে সাউথ এশিয়া ইনসিওরেন্স কোম্পানি লিমিটেড। সম্প্রতি কোম্পানির প্রধান নির্বাহী কর্মকর্তা মুহাম্মদ নুরুল আলম চৌধুরী মতিঝিল শাখার বীমাগ্রহীতা মেসার্স হ্যামকো লেদার্স লিমিটেডের সিনিয়র ম্যানেজার মো. মাসুদ পারভেজ ও ম্যানেজার মো. গোলাম মোস্তফার কাছে এ বীমা দাবির চেক হস্তান্তর করেন।\r\n\r\nএ সময় উপস্থিত ছিলেন সাউথ এশিয়া ইনসিওরেন্সের অতিরিক্ত ব্যবস্থাপনা পরিচালক ও মতিঝিল শাখার প্রধান মোহাম্মদ মোকলেছুর রহমান খান, সহকারী ব্যবস্থাপনা পরিচালক ও কোম্পানি সচিব মো. আব্দুর রাজ্জাক, এলএলএম, এসিএস, সহকারী ব্যবস্থাপনা পরিচালক ও শাখা নিয়ন্ত্রণ বিভাগের প্রধান মোরশেদ হাসান, এসইভিপি ও প্রধান অর্থ কর্মকর্তা মো. হুমায়ুন কবির শিমুল এবং ডেপুটি ভাইস প্রেসিডেন্ট ও দাবি ও পুনর্বীমা বিভাগের প্রধান মো. মাহফুজুর রহমান।- বিজ্ঞপ্তি', NULL, NULL, 'articles/5A4oAbHb28deUbzQRl14fOSDQiO93T653Q9OZPao.jpg', NULL, NULL, NULL, NULL, 12, 13, 1, NULL, 'published', 0, 0, 1, '2026-08-23 08:07:36', '2026-08-23 08:07:06', '2026-08-23 08:07:44', NULL),
	(26, 'আমদানিনির্ভরতা থেকে বেরিয়ে বিকল্প জ্বালানিতে যেতে চায় সরকার', 'আমদননরভরত-থক-বরয়-বকলপ-জবলনত-যত-চয়-সরকর', 'ডিসিসিআইয়ের সেমিনারে অর্থমন্ত্রী', 'সরকার আমদানিনির্ভরতা থেকে বেরিয়ে বিকল্প জ্বালানিতে যেতে চাচ্ছে বলে জানিয়েছেন অর্থ ও পরিকল্পনামন্ত্রী আমির খসরু মাহমুদ চৌধুরী।', 'তিনি বলেন, ‘চলতি অর্থবছরে পাঁচ হাজার মেগাওয়াট সোলার বিদ্যুৎ উৎপাদনের লক্ষ্যমাত্রা রয়েছে। একই সঙ্গে নিউক্লিয়ার ও কয়লাতেও জোর দিচ্ছি।’\r\n\r\nরাজধানীর মতিঝিলে ডিসিসিআই কার্যালয়ে গতকাল এক সেমিনারে এ কথা বলেন অর্থমন্ত্রী। ‘২০২৬ অর্থবছরের দ্বিবার্ষিক অর্থনৈতিক পরিস্থিতি: প্রেক্ষিত রাজস্ব ও মুদ্রানীতি এবং বেসরকারি খাতের প্রত্যাশা’ শীর্ষক এ সভার আয়োজক ঢাকা চেম্বার অব কমার্স অ্যান্ড ইন্ডাস্ট্রি (ডিসিসিআই)।', 'সেমিনারে প্রধান অতিথির বক্তব্যে আমির খসরু মাহমুদ চৌধুরী বলেন, ‘দেশে মজুদকৃত কয়লা উৎপাদনের চিন্তাভাবনা করছে সরকার। এক্ষেত্রে স্থানীয় বাসিন্দাদের সঙ্গে আলোচনার মাধ্যমে তাদের সুযোগ-সুবিধা নিশ্চিত করেই সেদিকে যেতে হবে। সেখানেও ১০ হাজার মেগাওয়াট সৌরবিদ্যুৎ উৎপাদন করা সম্ভব হবে।\r\n\r\nস্থানীয় বিনিয়োগ সম্প্রসারিত না হলে বিদেশী বিনিয়োগ আকর্ষণ সম্ভব নয় উল্লেখ করে তিনি বলেন, ‘বাণিজ্য ও বিনিয়োগে বিদ্যমান প্রতিবন্ধকতা যত গভীরেই থাকুক না কেন, সেগুলো নিরসন করতে সরকার প্রতিশ্রুতিবদ্ধ।’\r\n\r\nসেমিনারে মূল প্রবন্ধ উপস্থাপন করেন ডিসিসিআই সভাপতি তাসকীন আহমেদ। তিনি বলেন, ‘বাণিজ্য বাধা, মধ্যপ্রাচ্য সংকট, সরবরাহ চেইন প্রক্রিয়ায় প্রতিবন্ধকতা, জ্বালানি তেলের মূল্যবৃদ্ধি এবং পণ্য পরিবহনের খরচ দ্বিগুণ বৃদ্ধি পাওয়ার কারণে সামগ্রিক বিনিয়োগ ও ব্যবসা-বাণিজ্যে নিম্নমুখী প্রবণতা পরিলক্ষিত হচ্ছে। দীর্ঘ সময়ের জন্য বজায় থাকা উচ্চ মূল্যস্ফীতি, বেসরকারি খাতে নিম্নমুখী ঋণপ্রবাহ অর্থনীতির জন্য খুবই উদ্বেগজনক। এ পরিপ্রেক্ষিতে রফতানিতে লিডটাইম কমাতে শিল্পাঞ্চলগুলোর সব ধরনের সেবার নিরবচ্ছিন্ন প্রাপ্তি নিশ্চিত করতে হবে।’', 'বিশেষ অতিথির বক্তব্যে পাওয়ার অ্যান্ড পার্টিসিপেশন রিসার্চ সেন্টারের নির্বাহী চেয়ারম্যান ড. হোসেন জিল্লুর রহমান বলেন, ‘অর্থনীতির ক্ষেত্রে আমরা একটি যুগসন্ধিক্ষণে রয়েছি। এখানে সঠিক সিদ্ধান্ত নিতে না পারলে সামগ্রিক অর্থনীতিতে কাঙ্ক্ষিত গতি পরিলক্ষিত হবে না।’\r\n\r\nঅনুষ্ঠানে ইন্টারন্যাশনাল চেম্বার অব কমার্স বাংলাদেশের সভাপতি মাহবুবুর রহমান বলেন, ‘চলতি অর্থবছরের সামষ্টিক অর্থনৈতিক চিত্রে মূল্যস্ফীতি এখনো প্রত্যাশিত মাত্রায় নেমে আসেনি। বেসরকারি খাতে ঋণপ্রবাহও দীর্ঘদিনের মধ্যে সর্বনিম্ন পর্যায়ে রয়েছে। বিনিয়োগে স্থবিরতার পাশাপাশি শিল্প খাতও পূর্ণ সক্ষমতায় পরিচালিত হতে পারছে না। একই সঙ্গে উচ্চ সুদহার, উৎপাদন ও আমদানি ব্যয় বৃদ্ধি এবং জ্বালানি সরবরাহের অনিশ্চয়তা ব্যবসা পরিচালনার ব্যয় উল্লেখযোগ্যভাবে বৃদ্ধি করেছে।’\r\n\r\nপলিসি রিসার্চ ইনস্টিটিউটের চেয়ারম্যান ড. জায়েদি সাত্তার বলেন, ‘আমাদের নীতিমালা ও বাস্তবায়নের মধ্যে বেশ ফারাক রয়েছে। ফলে যেকোনো সিদ্ধান্তের কাঙ্ক্ষিত সুফল পাই না আমরা। রফতানি পণ্য ও বাজার বহুমুখীকরণে আমরা যতটা উদার, পণ্য আমদানিতে ততটাই কঠিন নীতিমালা। এর ফলে আমদানিতে উচ্চ শুল্কহার বজায় থাকছে এবং স্থানীয়ভাবে মূল্যস্ফীতি ও পণ্যের মূল্যও বাড়ছে।’\r\n\r\nবার্ষিক উন্নয়ন কর্মসূচি (এডিপি) বাস্তবায়ন করতে হলে কর আহরণে বিপ্লব ঘটাতে হবে বলে মনে করেন সিপিডির সম্মানিত ফেলো অধ্যাপক ড. মোস্তাফিজুর রহমান। তিনি বলেন, ‘বাজেটে ভালো কিছু উদ্যোগ রয়েছে, কিন্তু মুদ্রানীতিতে সেটির প্রতিফলন নেই। এর ফলে মূল্যস্ফীতি বাড়ছে। পরিস্থিতি মোকাবেলায় মুদ্রানীতির সংস্কার জরুরি।’\r\n\r\nনির্ধারিত আলোচনায় বাংলাদেশ উন্নয়ন গবেষণা প্রতিষ্ঠানের মহাপরিচালক ড. এ কে এনামুল হক বলেন, ‘বৈশ্বিক অর্থনৈতিক অস্থিরতার কারণে দেশের অর্থনীতিতে স্থিতিশীলতা প্রত্যাশা করা বেশ কঠিন। তাই ব্যাংকের তারল্য বাড়ানোর ওপর নজর দিতে হবে। পাশাপাশি বাণিজ্য সহায়ক পরিবেশ নিশ্চিতের বিকল্প নেই।’\r\n\r\nমিউচুয়াল ট্রাস্ট ব্যাংকের ব্যবস্থাপনা পরিচালক ও প্রধান নির্বাহী কর্মকর্তা (সিইও) সৈয়দ মাহবুবুর রহমান বলেন, ‘স্থানীয় বিনিয়োগ না বাড়লে বিদেশী বিনিয়োগ আসবে না। এজন্য নীতির ধারাবাহিকতা রক্ষার পাশাপাশি লজিস্টিকস খাতের দুর্বলতা কাটিয়ে উঠতে হবে।’\r\n\r\nট্রান্সকম লিমিটেডের গ্রুপ সিইও সীমিন রহমান বলেন, ‘বাজেটে ব্যবসাসহায়ক নীতি থাকলেও বেসরকারি খাতে কাঙ্ক্ষিত গতি আসেনি। এজন্য উচ্চ সুদহার ও মূল্যস্ফীতি, খেলাপি ঋণের উচ্চ হার এবং আর্থিক খাত থেকে সরকারের অধিক হারে ঋণ গ্রহণই প্রধানত দায়ী।’\r\n\r\nঅনুষ্ঠানে আরো বক্তব্য দেন ঢাকা চেম্বারের সাবেক সভাপতি হোসেন খালেদ, আবুল কাসেম খান, বেনজীর আহমেদ, রিজওয়ান রাহমান প্রমুখ।', 'articles/VgaShYMRN8ZTYKSigXIZZKocXaD0ZUldbZCek1pT.jpg', NULL, NULL, 'অর্থ ও পরিকল্পনামন্ত্রী আমির খসরু মাহমুদ চৌধুরী', 'অনলাইন', 12, NULL, 1, NULL, 'published', 0, 0, 10, '2026-08-23 08:12:29', '2026-08-23 08:12:29', '2026-08-25 02:18:25', NULL),
	(27, '‘সস্তি কপি’ বলে আক্রমণ, বলিউড দুই নায়িকার কথার লড়াই', 'সসত-কপ-বল-আকরমণ-বলউড-দই-নয়কর-কথর-লড়ই', NULL, NULL, 'বলিউডের অভিনেত্রী ও বিজেপি সাংসদ কঙ্গনা রনৌত ও অভিনেত্রী তাপসী পান্নুর পুরোনো দ্বন্দ্ব যেন আবারও প্রকাশ্যে ফিরেছে। সম্প্রতি কঙ্গনাকে নিয়ে মন্তব্য করেছিলেন তাপসী। এর জবাব দিতে গিয়ে সামাজিক যোগাযোগমাধ্যমে তাপসীকে তীব্র আক্রমণ করেছেন কঙ্গনা; যদিও পরে সেই পোস্টগুলো মুছে ফেলেছেন তিনি।\r\nতাপসী বর্তমানে তাঁর নতুন নেটফ্লিক্স সিনেমা ‘গান্ধারী’-এর প্রচারে ব্যস্ত। সিনেমাটির প্রচারণার অংশ হিসেবে দেওয়া এক সাক্ষাৎকারে কঙ্গনার সঙ্গে তাঁর পুরোনো দ্বন্দ্ব নিয়েও কথা বলেন তিনি।\r\n\r\nতাপসী বলেন, কঙ্গনার সঙ্গে তাঁর কখনো দেখা হয়নি। ২০১৯ সালে তাঁদের নিয়ে বিতর্ক শুরু হওয়ার সময়ও তাঁরা একে অপরের সঙ্গে দেখা করেননি। এখনো দেখা হয়নি।\r\n\r\nতাপসীর ভাষায়, কঙ্গনাকে নিয়ে তাঁর মতামত তাঁর নিজের বেড়ে ওঠা, কথা বলার ধরন এবং বিষয়গুলো দেখার দৃষ্টিভঙ্গির প্রতিফলন। কঙ্গনারও তাঁর নিজস্ব দৃষ্টিভঙ্গি রয়েছে। কে কোথা থেকে এসেছেন, সেটিই সবার জন্য অনেক কিছু বলে দেয়—এমন ইঙ্গিতও দেন তাপসী। তাপসীর এ মন্তব্যই ক্ষুব্ধ করেছে কঙ্গনাকে।\r\n\r\n‘সস্তি কপি’ বলে কটাক্ষ\r\nগতকাল শনিবার সন্ধ্যায় ইনস্টাগ্রাম স্টোরিতে তাপসীর নাম সরাসরি না নিয়ে কঙ্গনা লেখেন, ‘এক সস্তি কপি’ তাঁর নতুন বি-গ্রেড সিনেমার প্রচারে বেরিয়েছেন, কিন্তু বরাবরের মতো তাঁর সিনেমার চেয়ে সংবাদমাধ্যমের আগ্রহ বেশি কঙ্গনা রনৌতকে নিয়ে।\r\n\r\nএরপরই তাপসীর বিরুদ্ধে আরও ব্যক্তিগত আক্রমণ করেন কঙ্গনা। তিনি দাবি করেন, তাপসী তাঁর বেড়ে ওঠা ও মা–বাবাকে নিয়ে উপহাস করেছেন।\r\nকঙ্গনা লেখেন, সব মা–বাবা তাঁদের সন্তানদের জন্য সর্বোচ্চ চেষ্টা করেন। তিনি কখনো কোনো বিতর্কে প্রতিপক্ষের মা–বাবাকে টেনে আনেননি। তবে এবার তাপসীর মা-বাবাকে উদ্দেশ্য করে প্রশ্ন তুলেছেন তিনি—তাঁরা কেন তাঁর মা-বাবার মতো একজন ‘অরিজিনাল’ মানুষকে জন্ম দিতে পারলেন না।\r\n\r\nএরপর আরও একটি স্টোরিতে তাপসীকে সরাসরি আক্রমণ করেন কঙ্গনা।\r\n\r\nনিজের পরিবার নিয়েও বললেন কঙ্গনা\r\nকঙ্গনা দাবি করেন, অনেকেই তাঁর বেড়ে ওঠা, মা-বাবা ও পারিবারিক পরিচয় নিয়ে প্রশ্ন তোলেন। তাঁর ভাষ্য, শহরের প্রান্তিক এলাকায় ছোট ও স্যাঁতসেঁতে ভাড়া বাড়িতে বেড়ে ওঠা এবং ‘সন্দেহজনক’ পারিবারিক পটভূমির মানুষ প্রায়ই তাঁর পরিবারকে নিয়ে প্রশ্ন তোলেন।\r\n\r\nনিজের পারিবারিক পরিচয় তুলে ধরে কঙ্গনা বলেন, তিনি একটি পরিচিত রাজপুত জমিদার পরিবার থেকে এসেছেন এবং শিক্ষিত ও মর্যাদাসম্পন্ন মা-বাবার কাছে বড় হয়েছেন।\r\n\r\nঅভিনেত্রীর দাবি, তিনি নিজের পছন্দেই শূন্য থেকে ক্যারিয়ার শুরু করেছিলেন। তাই তাঁর মা-বাবাকে আক্রমণ করার কোনো কারণ নেই।\r\nতবে কঙ্গনার এ দুই স্টোরি বেশিক্ষণ ইনস্টাগ্রামে থাকেনি। আজ রোববার সকাল নাগাদ সেগুলো মুছে দেওয়া হয়।\r\n\r\n২০১৯ সালে শুরু দ্বন্দ্ব\r\nকঙ্গনা ও তাপসীর বিরোধ নতুন নয়। ২০১৯ সালে সামাজিক যোগাযোগমাধ্যমে এ দ্বন্দ্বের শুরু। কঙ্গনার বোন রঙ্গোলি চান্দেল সামাজিক যোগাযোগমাধ্যমে তাপসীকে কঙ্গনার ‘সস্তি কপি’ বা ‘সস্তা নকল’ বলে মন্তব্য করেছিলেন। এর পর থেকেই দুই অভিনেত্রীর সম্পর্ক নিয়ে আলোচনা শুরু হয়।\r\n\r\n২০২০ সালে বলিউডে স্বজনপ্রীতি ও ‘আউটসাইডার’ বিতর্ক যখন তুঙ্গে, তখন কঙ্গনা তাপসীসহ কয়েকজন অভিনেত্রীকে ‘বি-গ্রেড অভিনেত্রী’ এবং ‘নিডি আউটসাইডার’ বলে মন্তব্য করেন। সেই সময় পাল্টা জবাবও দিয়েছিলেন তাপসী।', NULL, NULL, 'articles/theNBouy9b9PGrIC3iVN27LXQsPcmjoeriZuiS87.png', NULL, NULL, NULL, NULL, 30, 31, 1, NULL, 'published', 0, 0, 4, '2026-08-23 08:40:32', '2026-08-23 08:40:32', '2026-08-25 02:25:00', NULL),
	(28, 'দুর্ঘটনা থেকে আইসিইউ, কেমন আছেন অভিনেত্রী মেঘলা মুক্তা', 'দরঘটন-থক-আইসইউ-কমন-আছন-অভনতর-মঘল-মকত', NULL, NULL, 'সড়ক দুর্ঘটনায় গুরুতর আহত হয়েছিলেন মডেল ও অভিনেত্রী মেঘলা মুক্তা। অস্ত্রোপচারের পর ছিলেন আইসিইউতে। দীর্ঘ চিকিৎসা শেষে সম্প্রতি বাসায় ফিরেছেন তিনি। তবে দুর্ঘটনার পর শারীরিক ও মানসিকভাবে কঠিন সময় পার করছেন এই অভিনেত্রী। সামাজিক মাধ্যমে নিজের বর্তমান পরিস্থিতির কথা জানিয়েছেন তিনি।\r\n\r\nরোববার এক পোস্টে মেঘলা মুক্তা লেখেন, হাসপাতাল থেকে বাসায় ফেরার পর তিনি বুঝতে পারছেন, এই সময়টা অনেকটাই একা কাটছে। তার ভাষায়, ‘কোনো বন্ধু, কোনো কাজ, কোনো মিটিং—কিছুই নেই। শুধু আমি, আমার রুম, টিভি, ফোন, আর মাঝে মাঝে পড়ার চেষ্টা।’', NULL, NULL, 'articles/wdWv3fiuupli2xioaTtder4fvoTVUmM6OHSbCOm9.webp', NULL, NULL, NULL, NULL, 30, 35, 1, NULL, 'published', 0, 0, 2, '2026-08-23 08:43:45', '2026-08-23 08:43:45', '2026-08-26 07:15:40', NULL),
	(29, 'মেগানের অভিনয়ে ফেরা নিয়ে নতুন জটিলতা', 'মগনর-অভনয়-ফর-নয়-নতন-জটলত', NULL, NULL, 'বিয়ের পর অভিনয় থেকে দীর্ঘ বিরতিতে ছিলেন ব্রিটিশ রাজপরিবারের সদস্য প্রিন্স হ্যারির স্ত্রী মেগান মার্কেল। তবে অভিনয়ে ফেরার সম্ভাবনার মধ্যে তৈরি হয়েছে নতুন জটিলতা। গাই রিচির জনপ্রিয় নেটফ্লিক্স সিরিজ ‘দ্য জেন্টলমেন’-এর তৃতীয় মৌসুমে মেগানের অভিনয়ের খবর প্রকাশের একদিন পরই তার কাস্টিং বাতিল করা হয়েছে বলে দাবি উঠেছে।\r\n\r\nশনিবার ‘ভ্যানিটি ফেয়ার’ ও ‘দ্য নিউ ইয়র্কার’-এর সাবেক সম্পাদক টিনা ব্রাউন সামাজিক মাধ্যমে দাবি করেন, ‘দ্য জেন্টলমেন’-এর তৃতীয় মৌসুমে মেগানের কাস্টিং প্রত্যাহার করা হয়েছে।', NULL, NULL, 'articles/oOc065y5HX7nyUGqvVqYBbq0PoaSMAJKUxt0yfvx.webp', NULL, NULL, NULL, NULL, 30, 37, 1, NULL, 'published', 0, 0, 21, '2026-08-23 08:46:12', '2026-08-23 08:46:12', '2026-08-25 02:24:42', NULL),
	(30, 'সরকারের ছয় মাসে ৩১ সূচকের ১৯টিতে অবনতি, স্বস্তি ১২টিতে', 'সরকরর-ছয়-মস-৩১-সচকর-১৯টত-অবনত-সবসত-১২টত', 'সিপিডির মূল্যায়ন', 'নতুন সরকারের প্রথম ছয় মাসে অর্থনৈতিক পুনরুদ্ধার কার্যক্রমে নেতিবাচক প্রবণতাই বেশি দেখছে বেসরকারি গবেষণা সংস্থা সেন্টার ফর পলিসি ডায়ালগ (সিপিডি)। প্রধান ৩১টি সূচকের মধ্যে ১৯টিতেই অবনতি হয়েছে।', 'মূল্যস্ফীতি, মাথাপিছু ঋণ, রাজস্ব আদায়, শিল্পে গ্যাস-বিদ্যুৎ সংকটসহ বেশ কয়েকটি গুরুত্বপূর্ণ খাতের পরিস্থিতি উদ্বেগজনক পর্যায়ে রয়েছে। সূচকের বাকি ১২টিতে অগ্রগতি লক্ষ্য করা গেছে। তবে এসব সূচকের অগ্রগতিও টেকসই নয়। অবশ্য, পরিস্থিতি অস্বস্থিকর বললেও হতাশ হওয়ার মতো নয় বলে মনে করে সিপিডি। \r\n\r\nসরকারের প্রথম ১৮০ দিনের অর্থনৈতিক পরিস্থিতি মূল্যায়নে এই পর্যবেক্ষণ তুলে ধরেছে সিপিডি। সোমবার এক মিডিয়া সংলাপে এই পর্যবেক্ষণ তুলে ধরা হয়। সরকারের প্রতিশ্রুতি ও পদক্ষেপ সংক্রান্ত ৯টি খাতের ৩৬২ পর্যবেক্ষণে সিপিডির মূল্যায়নে স্বস্তি ও অস্বস্তির দিকগুলো তুলে ধরা হয়। খাতগুলোর মধ্যে রয়েছে, শাসন ও প্রশাসন, সরকারি অর্থ ব্যবস্থাপনা, শিল্প ও বাণিজ্য, ব্যাংক ও আর্থিক খাত, জ্বালানি ও পরিবহন, কৃষি, শিক্ষা, স্বাস্থ্য এবং সামাজিক সুরক্ষা। শুধু ঘোষণার পরিবর্তে বাস্তবে নেওয়া পদক্ষেপগুলোকেই  সিপিডির মূল্যায়নের আওতায় আনা হয়েছে।\r\n\r\n‘সরকারের ছয় মাস: পারফরম্যান্স পর্যালোচনা’ শীর্ষক সংলাপটি রাজধানীর ধানমন্ডিতে সিপিডির কার্যালয়ে অনুষ্ঠিত হয়। এতে সিপিডির পর্যবেক্ষণ তুলে ধরেন সংস্থার সম্মাননীয়  ফেলো ড. দেবপ্রিয় ভট্টাচার্য। অন্যদের মধ্যে সিপিডির সম্মাননীয় ফেলো অধ্যাপক মোস্তাফিজুর রহমান, অতিরিক্ত গবেষণা পরিচালক তৌফিকুল ইসলাম খান সংলাপে অংশ নেন। \r\n\r\nবেতন বাড়ানো সম্পর্কিত এক প্রশ্নের জবাবে দেবপ্রিয় ভট্টাচার্য বলেন, সরকারি চাকরিজীবীদের জন্য নতুন বেতন কাঠামো করতে সরকার রাজনৈতিক সাহস দেখাতে পারছে না। বিষয়টিকে ঝুলিয়ে রাখলে সমস্যা কমবে না, বরং যত দেরি হবে, পরিস্থিতি তত জটিল হবে। \r\n\r\nতিনি বলেন, এত দেরি না করে শুরুতেই যদি ২০-২৫ শতাংশ মহার্ঘ ভাতা দিয়ে নুতন বেতন কাঠামো বাস্তবায়নে সময় চাইতেন সেটা ভালো হতো। বিষয়টিকে ঝুলিয়ে রাখলে সমস্যা কমবে না, বরং যত দেরি হবে, পরিস্থিতি তত জটিল হবে। এতে সরকারের অন্যান্য কাজও বিঘ্নিত হবে।\r\n\r\nমূল উপস্থাপনায় দেবপ্রিয় ভট্টাচার্য বলেন, নতুন সরকারের কাছে জনগণের প্রধান প্রত্যাশা ছিল অর্থনীতি ঘুরে দাঁড়াবে এবং সুশাসন প্রতিষ্ঠিত হবে। কিন্তু গত ছয় মাসের মূল্যায়নে এ দুই ক্ষেত্রে আশাব্যঞ্জক অগ্রগতি দেখা যায়নি; বরং দুই ক্ষেত্রেই এক ধরনের অস্বস্তি তৈরি হয়েছে। \r\n\r\nতিনি বলেন, বর্তমান সরকার আগের সরকারের কাছ থেকে ভঙ্গুর অর্থনীতি পেয়েছে। টাকা সংকট, ব্যাংকিং খাতের দুরবস্থা, অনাদায়ী ঋণ, অর্থপাচার ও রাজস্ব ঘাটতির মতো বড় চ্যালেঞ্জ ছিল। তবে এসব মোকাবিলা করে অর্থনীতিকে ঘুরে দাঁড় করানোর ক্ষেত্রে প্রত্যাশিত গতি দেখা যায়নি।  \r\n\r\nসিপিডির মূল্যায়নে, অর্থনৈতিক প্রবৃদ্ধি ধারাবাহিকভাবে কমে ৩ শতাংশের নিচে নেমেছে। রাজস্ব আদায়ে বড় ঘাটতি তৈরি হয়েছে। পাশাপাশি শিল্প খাতে দীর্ঘস্থায়ী গ্যাস ও বিদ্যুৎ সংকটের কারণে নতুন বিনিয়োগ বাধাগ্রস্ত হচ্ছে। দায়িত্ব নেওয়ার সময় মূল্যস্ফীতি, তারল্য সংকট ও বাজারের অস্থিতিশীলতার যে চ্যালেঞ্জ ছিল, ছয় মাস পরও তা পুরোপুরি কাটেনি।\r\n\r\nসুশাসন প্রসঙ্গে দেবপ্রিয় ভট্টাচার্য বলেন, দুর্নীতি, চাঁদাবাজি, দখলবাজি, সিন্ডিকেট ও ‘মব কালচার’ বন্ধের প্রতিশ্রুতি থাকলেও বাস্তবে কাঙ্ক্ষিত পরিবর্তন দেখা যায়নি। রাজনৈতিকভাবে সংশ্লিষ্ট ব্যক্তিদের উচ্চপদে পদায়নের বিষয়েও তিনি প্রশ্ন তোলেন। সরকারের ‘জিরো টলারেন্স’ ঘোষণার পরও মব সহিংসতা অব্যাহত রয়েছে।', NULL, NULL, 'articles/dm19IE1AbFojvGTvunsiWqYVcrVamEnvDGkIfT6F.webp', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 1, 1, 17, '2026-08-24 09:55:44', '2026-08-24 09:55:44', '2026-08-26 07:27:04', NULL),
	(31, 'পটুয়াখালী বিশ্ববিদ্যালয়ে র‍্যাগিংয়ের ঘটনায় ১৩ শিক্ষার্থীকে শাস্তি', 'পটয়খল-বশববদযলয়-রযগয়র-ঘটনয়-১৩-শকষরথক-শসত', 'বিশ্ববিদ্যালয়ে র‍্যাগিং', 'পটুয়াখালী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয়ে নবীন এক শিক্ষার্থীকে র‍্যাগিংয়ের ঘটনায় জড়িত ১৩ শিক্ষার্থীর বিরুদ্ধে শাস্তিমূলক ব্যবস্থা নিয়েছে বিশ্ববিদ্যালয় প্রশাসন', 'গতকাল সোমবার বিকেলে বিশ্ববিদ্যালয়ের রেজিস্ট্রার জামাল হোসেনের সই করা অফিস আদেশে এ তথ্য জানানো হয়। শাস্তির আওতায় আসা শিক্ষার্থীরা হলেন মো. আসিফ জাহান, প্রিয় কুমার সাহা, তৌফিক হোসেন আলী, মনুয়িস তাজওয়ার মাহি, আশরাফুল ইসলাম, সাকিব হোসেন মজুমদার, মুমিনুল ইসলাম, উৎস বর্মণ, মো. নাহিম, মোহাম্মদ মুজাহিদুল ইসলাম, জোবায়ের আহমেদ লিমন, মো. রাজিব মিয়া ও রক্ষণ চন্দ্র রায়। তাঁরা বিভিন্ন অনুষদের দ্বিতীয় বর্ষের শিক্ষার্থী এবং বিজয়-২৪ হলের আবাসিক।', 'ওই শিক্ষার্থীদের কয়েকজনকে ৫ থেকে ২০ হাজার টাকা পর্যন্ত জরিমানা, এক সেমিস্টার থেকে এক বছর পর্যন্ত হল ও ক্লাস থেকে বহিষ্কার এবং অভিভাবকের উপস্থিতিতে মুচলেকা দেওয়ার নির্দেশ দেওয়া হয়েছে। একই ধরনের অপরাধে আবার জড়ালে তাঁদের স্থায়ীভাবে বহিষ্কারের সতর্কতাও জানানো হয়েছে।\r\n\r\nবিশ্ববিদ্যালয়ের আদেশে বলা হয়েছে, এক নবীন শিক্ষার্থীর অভিযোগের পর তদন্ত কমিটি গঠন করা হয়। ওই কমিটির দেওয়া প্রতিবেদন পর্যালোচনা করে বিশ্ববিদ্যালয়ের শৃঙ্খলা পরিষদের সিদ্ধান্ত অনুযায়ী ওই শিক্ষার্থীদের বিরুদ্ধে ব্যবস্থা নেওয়া হয়েছে। তদন্তে র‍্যাগিংয়ের পরিকল্পনা, নেতৃত্ব ও অংশগ্রহণের পাশাপাশি শারীরিক ও মানসিক নির্যাতনের অভিযোগের সত্যতা পাওয়া গেছে।', '১৯ আগস্ট রাতে আইন ও ভূমি প্রশাসন অনুষদের ২০২৫-২৬ শিক্ষাবর্ষের নবীন শিক্ষার্থী হাবিবকে বিজয়-২৪ হলের কমনরুমে নিয়ে র‍্যাগিংয়ের অভিযোগ ওঠে। এতে তিনি অসুস্থ হয়ে পড়লে প্রথমে দুমকি উপজেলা স্বাস্থ্য কমপ্লেক্সে চিকিৎসা দেওয়া হয়। পরে অবস্থার অবনতি হলে তাঁকে বরিশালের শের-ই-বাংলা মেডিকেল কলেজ হাসপাতালে ভর্তি করা হয়।\r\n\r\nএ ঘটনায় পর বিশ্ববিদ্যালয় প্রশাসনের কাছে লিখিত অভিযোগ করেন হাবিব। অভিযোগের পরিপ্রেক্ষিতে বিজয়-২৪ হলের প্রভোস্ট মাসুদুর রহমানকে আহ্বায়ক করে পাঁচ সদস্যের তদন্ত কমিটি গঠন করা হয়। কমিটিকে তিন কার্যদিবসের মধ্যে প্রতিবেদন দিতে বলা হয়। নির্ধারিত সময়ের মধ্যেই কমিটি প্রতিবেদন জমা দেয়।\r\n\r\nবিশ্ববিদ্যালয়ের রেজিস্ট্রার জামাল হোসেন বলেন, নির্ধারিত সময়ের মধ্যে জরিমানা পরিশোধ ও মুচলেকা দাখিল না করলে সংশ্লিষ্টদের বিরুদ্ধে নির্ধারিত শাস্তি কার্যকর করা হবে।', 'articles/s6OhZGbWzgTEYX5dlOBGgclnNGnUGoFJjyTSMDYf.png', 'প্রতিনিধি', 'পটুয়াখালী', 'পটুয়াখালী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয়ে মূল ফটক', 'অনলাইন', 5, 7, 1, NULL, 'published', 0, 1, 16, '2026-08-25 01:12:52', '2026-08-25 01:12:52', '2026-08-26 07:12:45', NULL),
	(32, 'সরকারের বিরুদ্ধে কথা বলার স্বাধীনতা সবারই আছে: তথ্যমন্ত্রী', 'সরকরর-বরদধ-কথ-বলর-সবধনত-সবরই-আছ-তথযমনতর', NULL, 'গণমাধ্যমের স্বাধীনতা প্রসঙ্গে আন্দালিভ রহমান বলেন, গণতন্ত্র বিশ্বাস করাটা একটি মানসিকতার বিষয়।', 'গত ১৭ বছর যে মানসিকতা আমরা দেখেছি, তা ছিল সমালোচনার বিরুদ্ধে অবস্থান নেয়া। কিন্তু বর্তমান সরকার কিংবা প্রধানমন্ত্রীর দিক থেকে মিডিয়ার স্বাধীনতা বন্ধ করে দেওয়া বা গণমাধ্যমকে নিয়ন্ত্রণ করার কোনো মানসিকতা নেই।সরকারের বিরুদ্ধে কথা বলার স্বাধীনতা সবার রয়েছে বলে মন্তব্য করেছেন তথ্য ও সম্প্রচারমন্ত্রী আন্দালিভ রহমান। তিনি বলেছেন, গণমাধ্যমের স্বাধীনতা বন্ধ করা বা নিয়ন্ত্রণ করার কোনো মানসিকতা বর্তমান সরকার কিংবা প্রধানমন্ত্রীর নেই। বরং সরকারের ভুলত্রুটি তুলে ধরে বস্তুনিষ্ঠ সমালোচনা করার আহ্বান জানিয়েছেন তিনি। খবর বাসস।', 'সচিবালয়ে তথ্য অধিদপ্তরের (পিআইডি) সম্মেলন কক্ষে আজ সরকারের বিভিন্ন কার্যক্রমের অগ্রগতি নিয়ে আয়োজিত সাপ্তাহিক ব্রিফিংয়ে সাংবাদিকদের প্রশ্নের জবাবে তথ্যমন্ত্রী এসব কথা বলেন।\r\n\r\nগণমাধ্যমের স্বাধীনতা প্রসঙ্গে আন্দালিভ রহমান বলেন, ‘গণতন্ত্র বিশ্বাস করাটা একটি মানসিকতার বিষয়। গত ১৭ বছর যে মানসিকতা আমরা দেখেছি, তা ছিল সমালোচনার বিরুদ্ধে অবস্থান নেয়া। কিন্তু বর্তমান সরকার কিংবা প্রধানমন্ত্রীর দিক থেকে মিডিয়ার স্বাধীনতা বন্ধ করে দেওয়া বা গণমাধ্যমকে নিয়ন্ত্রণ করার কোনো মানসিকতা নেই।’\r\n\r\nতিনি বলেন, গত ১৭ বছরে দেশের সব সিস্টেম দুর্নীতিগ্রস্ত ছিল। এমন একটি ভঙ্গুর অবস্থার পর দায়িত্ব নিয়ে সরকার দেশের ইতিহাসের অন্যতম কঠিন সময় পার করছে। এ অবস্থায় সরকারের ভুলত্রুটি শুধরে সঠিক পথে এগিয়ে যেতে গণমাধ্যমের বস্তুনিষ্ঠ সমালোচনা প্রয়োজন।\r\n\r\nবুদ্ধিবৃত্তিক ফ্যাসিজমের সমালোচনা করে তথ্যমন্ত্রী বলেন, কোনো গণমাধ্যম বা ব্যক্তি বুদ্ধিবৃত্তিক চিন্তা-চেতনায় ফ্যাসিজমকে সমর্থন, প্রচার বা চর্চা করলে তাদের সামাজিকভাবে ধিক্কার ও বয়কট করা ছাড়া অন্য কিছু করার নেই। যারা মুক্ত বাংলাদেশ ও নতুন স্বাধীন বাংলাদেশের চেতনায় বিশ্বাস করে না, সামাজিকভাবে বয়কট হওয়াই তাদের জন্য সবচেয়ে বড় বিচার বলেও মন্তব্য করেন তিনি।', 'ব্রিফিংয়ের শুরুতে সরকারের ছয় মাসের বিশেষ অর্জন নিয়ে তথ্য অধিদপ্তর প্রকাশিত ‘আই হ্যাভ এ প্ল্যান: গণতান্ত্রিক অভিযাত্রার ৬ মাস’ শীর্ষক বইয়ের মোড়ক উন্মোচন করেন তথ্যমন্ত্রী।\r\n\r\nশেখ হাসিনা প্রসঙ্গে এক প্রশ্নের জবাবে আন্দালিভ রহমান বলেন, তিনি বর্তমানে ভারতে অবস্থান করছেন। ভারতীয় সংবাদমাধ্যমের খবর অনুযায়ী বিষয়টি আদালত বা বিচারিক প্রক্রিয়ার মাধ্যমে নিষ্পত্তির চেষ্টা চলছে। তবে জুলাই আন্দোলনসহ বিগত সময়ের সব অপরাধের সঠিক বিচারের স্বার্থে যাদের নামে মামলা রয়েছে, তাদের সবাইকে ফেরত আনা হবে—বাংলাদেশ সরকারের অবস্থান এমনই বলে জানান তিনি।\r\n\r\nসংবাদপত্রের ভুয়া প্রচারসংখ্যা বন্ধের বিষয়ে তথ্যমন্ত্রী বলেন, কম পত্রিকা ছাপিয়ে লক্ষাধিক সার্কুলেশন দেখানোর অসত্য প্রক্রিয়া বন্ধে তথ্য ও সম্প্রচার মন্ত্রণালয় জোরালোভাবে কাজ শুরু করেছে।\r\n\r\nব্রিফিংয়ে তথ্য ও সম্প্রচার প্রতিমন্ত্রী ইয়াসের খান চৌধুরী বলেন, সরকারের বিরুদ্ধে কথা বলার স্বাধীনতা সবার রয়েছে। সরকারের পক্ষে বা বিপক্ষে—জনগণের কথা তুলে ধরাই গণতন্ত্র। বিটিভি ও সরকারি মাধ্যমে আনুপাতিক হারে বিরোধী দলগুলোর খবরও প্রচারের নির্দেশনা দেয়া হয়েছে বলে জানান তিনি।\r\n\r\nএছাড়া সাংবাদিকদের কল্যাণে ট্রাস্ট ফান্ডের অনুদান দ্বিগুণ করার জন্য অর্থ মন্ত্রণালয়ে আবেদন করা হয়েছে বলে জানান প্রতিমন্ত্রী। অসুস্থ ও অসচ্ছল সাংবাদিকদের জন্য ইতোমধ্যে এক কোটি টাকা হস্তান্তর করা হয়েছে বলেও তিনি জানান।\r\n\r\nব্রিফিংয়ে তথ্য ও সম্প্রচার সচিব মাহবুবা ফারজানা এবং তথ্য অধিদপ্তরের প্রধান তথ্য কর্মকর্তা সৈয়দ আবদাল আহমদ উপস্থিত ছিলেন।', 'articles/rCAkprexg6ap2yQEQ4vyUFQm1ION9XVL5DAgPojv.jpg', NULL, NULL, 'সচিবালয়ে তথ্য অধিদপ্তরের (পিআইডি) সম্মেলন কক্ষে  আয়োজিত সাপ্তাহিক ব্রিফিংয়ে তথ্যমন্ত্রী আন্দালিভ রহমান', 'বাসস', 5, 6, 1, NULL, 'published', 1, 0, 10, '2026-08-25 03:30:13', '2026-08-25 03:30:13', '2026-08-29 09:30:04', NULL),
	(33, 'সৌরবিদ্যুতে ঝুঁকছে বড় শিল্পগোষ্ঠী, নিজেরাই উৎপাদন করতে পারে ৬০০ মেগাওয়াট', 'সরবদযত-ঝকছ-বড-শলপগষঠ-নজরই-উৎপদন-করত-পর-৬০০-মগওযট', 'বিদ্যুৎ সংকট', 'দেশের অন্যতম শীর্ষস্থানীয় শিল্পগোষ্ঠী ডিবিএল গ্রুপ তাদের ৭টি তৈরি পোশাক ও টেক্সটাইল কারখানার ছাদে ৫ দশমিক ৫ মেগাওয়াট ক্ষমতার সৌরবিদ্যুৎ উৎপাদন ইউনিট স্থাপন করেছে।', 'পাশাপাশি নতুন করে সিরামিক, তৈরি পোশাকসহ ১০টি কারখানায় ১৬ মেগাওয়াটের সৌরবিদ্যুৎ বসানোর পরিকল্পনা নিয়েছে তারা। এর মধ্যে চলতি বছর উৎপাদনে আসবে ৮ মেগাওয়াট। বাকিটা আগামী বছর। জানতে চাইলে ডিবিএল গ্রুপের ভাইস চেয়ারম্যান এম এ রহিম প্রথম আলোকে বলেন, ‘আমাদের বিভিন্ন প্রতিষ্ঠানের জ্বালানিনিরাপত্তা ও বিদেশি ক্রেতাদের কার্বন নিঃসরণের চাপ থাকায় আমরা দ্রুত সৌরবিদ্যুতে বিনিয়োগ করছি। নতুন প্রযুক্তি আসায় এখন সৌরবিদ্যুৎ স্থাপনে আগের চেয়ে সময় কম লাগছে। কারখানার ছাদের সৌরবিদ্যুতে প্রতি ইউনিটে খরচ পড়ছে ৬ থেকে সাড়ে ৬ টাকা।’', 'ডিবিএল গ্রুপের মতো বড় শিল্পকারখানাগুলো এখন দ্রুতগতিতে সৌরবিদ্যুতের দিকে ঝুঁকছে। গত দশকে সরকারের নীতি ও বিদেশি ক্রেতাদের কার্বন নিঃসরণ কমানোর চাপে পড়ে সৌরবিদ্যুৎ স্থাপন শুরু হয়। জ্বালানিসংকট প্রকট হওয়ার পাশাপাশি জ্বালানির দাম বাড়তে থাকায় তিন বছর ধরে সৌরবিদ্যুতে বিনিয়োগ বাড়াচ্ছে বড় বড় শিল্পগোষ্ঠী।\r\n\r\nসৌরবিদ্যুৎ স্থাপনের সঙ্গে যুক্ত একাধিক প্রতিষ্ঠানের কর্তাব্যক্তিরা জানান, শিল্পকারখানার ছাদে সৌরবিদ্যুতের যতগুলো বড় প্ল্যান্ট হয়েছে, তার অধিকাংশই হয়েছে গত দুই বছরে। ইতিমধ্যে বিভিন্ন শিল্পকারখানায় ৬০০ মেগাওয়াটের বেশি উৎপাদনক্ষমতার সৌরবিদ্যুৎ ইউনিট স্থাপিত হয়েছে। তার মধ্যে বেশির ভাগই রপ্তানিমুখী তৈরি পোশাকশিল্পে।', 'যদিও ছাদভিত্তিক সৌরবিদ্যুৎ–শিল্পের বিদ্যুতের পুরো চাহিদা পূরণ করতে পারে না। তবে কারখানার তিন–চার ঘণ্টা পর্যন্ত কার্যক্রম সচল রাখতে সহায়তা করে। সৌরবিদ্যুতের মাধ্যমে কারখানার মোট বিদ্যুৎ–চাহিদার ৫-১৫ শতাংশ পর্যন্ত পূরণ হয়। যদিও কারখানাভেদে এই হার বেশিও হয়। ফলে দিনের বেলায় জাতীয় গ্রিডের বিদ্যুতের ওপর চাপ কিছুটা হলেও কমাতে পেরেছে এসব শিল্পকারখানার ছাদভিত্তিক সৌরবিদ্যুৎ—এমনটাই জানান সৌরবিদ্যুৎ উৎপাদনের সঙ্গে যুক্ত শিল্পের কর্তাব্যক্তিরা।\r\n\r\nসংশ্লিষ্ট সূত্রে জানা যায়, আবুল খায়ের স্টিল, ওয়ালটন, হা-মীম গ্রুপ, প্রাণ–আরএফএল গ্রুপ, বিএসআরএম, ইয়ংওয়ান গ্রুপ, মেঘনা গ্রুপ অব ইন্ডাস্ট্রিজ (এমজিআই), প্যাসিফিক জিনস গ্রুপ, টিম গ্রুপ, ডিবিএল গ্রুপ, রাইজিং গ্রুপ, ঊর্মি গ্রুপ, মাইক্রোফাইবার গ্রুপ, পলমল গ্রুপ, অ্যাপেক্স ফুটওয়্যার, কর্ণফুলী শু ইন্ডাস্ট্রিজ, মাসকো গ্রুপসহ বিভিন্ন শিল্পপ্রতিষ্ঠান ইতিমধ্যে তাদের কারখানায় বিভিন্ন ক্ষমতার সৌরবিদ্যুৎ ইউনিট স্থাপন করেছে।\r\n\r\n\r\nশিল্পের ছাদে বসছে সৌরবিদ্যুৎ\r\n\r\nদেশের শিল্পকারখানা ও বাণিজ্যিক প্রতিষ্ঠানের ছাদে বসানো সৌরবিদ্যুতের ক্ষমতা যে বাড়ছে, সে বিষয়ে ধারণা পাওয়া যায় যুক্তরাষ্ট্রভিত্তিক জ্বালানিবিষয়ক গবেষণাপ্রতিষ্ঠান ইনস্টিটিউট ফর এনার্জি ইকোনমিকস অ্যান্ড ফাইন্যান্সিয়াল অ্যানালাইসিসের (আইইইএফএ) এক প্রতিবেদনে।\r\n\r\nগত ৪ আগস্ট প্রকাশিত সংস্থাটির এক প্রতিবেদনে বলা হয়, সরকারি হিসাবে দেশে বর্তমানে ছাদে স্থাপন করা সৌরবিদ্যুতের উৎপাদনসক্ষমতা ৪১৮ মেগাওয়াট। তবে আইইইএফএর হিসাবে, ২৩৯টি বড় শিল্পকারখানার ছাদে স্থাপন করা সৌরবিদ্যুতের প্রকৃত সক্ষমতা ৬৬৭ মেগাওয়াটে পৌঁছেছে।\r\n\r\nআইইইএফএর প্রতিবেদনে বলা হয়েছে, বড় শিল্পকারখানার পাশাপাশি ছোট ছোট স্থাপনার ছাদে স্থাপন করা সৌরবিদ্যুৎ হিসাবের আওতায় আনলে বাংলাদেশের ছাদভিত্তিক সৌরবিদ্যুতের মোট উৎপাদনসক্ষমতা ১ হাজার মেগাওয়াট পর্যন্ত হতে পারে। এতে দিনের বেলায় বিদ্যুতের চাহিদা সামান্য কমেছে। ২০২৪ সালের ১৬ এপ্রিল থেকে ১১ জুনের সঙ্গে চলতি বছরের একই সময়ের বিদ্যুতের চাহিদার তুলনামূলক বিশ্লেষণ করে এই তথ্যের সত্যতা মিলেছে বলে দাবি করেছে আইইইএফএ।\r\n\r\nদেশের শীর্ষস্থানীয় শিল্পগোষ্ঠী প্রাণ-আরএফএল তাদের বিভিন্ন কারখানার ছাদে ১০০ মেগাওয়াটের বেশি সৌরবিদ্যুৎ উৎপাদনের পরিকল্পনা করেছে। ২০টি কারখানায় ইতিমধ্যে ৩৫ মেগাওয়াট বিদ্যুৎ উৎপাদন হচ্ছে। এ বছরের মধ্যে আরও অন্তত ৩০ মেগাওয়াট যুক্ত হতে পারে। নিজেদের কারখানা ব্যবহারের পাশাপাশি দুটি কারখানা থেকে জাতীয় গ্রিডে বিদ্যুৎ সরবরাহ করা হচ্ছে।\r\n\r\nকারখানার ছাদে বিদ্যুৎ উৎপাদন বাড়াচ্ছে আরেক বড় গোষ্ঠী আকিজ বশির গ্রুপ। তাদের জনতা জুট মিলসে ২১ মেগাওয়াট উৎপাদনসক্ষমতা তৈরি করা হয়েছে। এখন চাহিদার শতভাগ বিদ্যুৎ ছাদ থেকে পাচ্ছে পাটকলটি। হবিগঞ্জে আকিজ গ্লাসের কারখানার ছাদে ১৩ মেগাওয়াট উৎপাদনক্ষমতার সৌরবিদ্যুৎ ইউনিট বসানো হয়েছে, যার মধ্যে ৮ মেগাওয়াট ব্যাটারি সিস্টেম আছে। এতে রাতেও বিদ্যুৎ পায় কারখানাটি। ২০২২ সালে উৎপাদন শুরু করে তারা। এখন সব মিলে ছাদ থেকে ৭৫ মেগাওয়াট বিদ্যুৎ উৎপাদন করছে আকিজ বশির। আরও ২৮ মেগাওয়াট উৎপাদনসক্ষমতা বাড়ানোর কাজ চলছে বর্তমানে।', 'articles/exMJDdM1QUSxUmw5IaXG1f8RG8nSvjRbotXKeUZH.jpg', NULL, NULL, 'মেঘনা সিরামিক ইন্ডাস্ট্রিজের কারখানা', 'অনলাইন', 12, 13, 1, NULL, 'published', 1, 0, 13, '2026-08-26 01:01:57', '2026-08-26 01:01:57', '2026-08-30 20:55:01', NULL),
	(34, 'নেপাল-তিব্বত সীমান্তে আকস্মিক বন্যা ও ভূমিধসে ১৮ জনের মৃত্যু, বিদেশী পর্যটকসহ নিখোঁজ অন্তত ৪০০', 'নপল-তববত-সমনত-আকসমক-বনয-ও-ভমধস-১৮-জনর-মতয-বদশ-পরযটকসহ-নখজ-অনতত-৪০০', 'ভূমিকম্প', 'নেপাল ট্যুরিজম বোর্ড মোট ৩৮৪ জন পর্যটককে নিখোঁজ হিসেবে শনাক্ত করেছে। এদের মধ্যে ২৯১ জন বিদেশী নাগরিক এবং ৯৩ জন নেপালি নাগরিক। নিখোঁজ বিদেশীদের মধ্যে ১২ জন ব্রিটিশ নাগরিক, ১০৫ জন ভারতীয়, ৩৭ জন অনাবাসী ভারতীয় (এনআরআই), ১৭ জন মালয়েশীয়, ৪ জন দক্ষিণ আফ্রিকান, ৩ জন আমেরিকান, ১ জন অস্ট্রেলীয় এবং ১ জন ডাচ নাগরিক বলে নিশ্চিত হওয়া গেছে। এ ছাড়া আরো ১১১ জন নিখোঁজের জাতীয়তা এখনো নিশ্চিত হওয়া যায়নি।', 'নেপাল-তিব্বত সীমান্তে আকস্মিক বন্যা ও ভূমিধসে অন্তত ১৮ জনের মৃত্যু হয়েছে। প্লাবিত হয়েছে একাধিক গ্রাম, ক্ষতিগ্রস্ত হয়েছে ঘরবাড়ি ও সড়ক অবকাঠামো। এ ঘটনায় এখনো পর্যন্ত অন্তত ৪০০ জন নিখোঁজ রয়েছেন। খবর বিবিসি।\r\n\r\nস্থানীয় সময় বুধবার সকালে ৮টা ৩৭ মিনিটে অনুভূত একটি ভূমিকম্পের পর তুষারধস নামে। এতে গলিত বরফের পানি দ্রুত পাহাড়ি নদী ‘ভোটে কোশি’তে আছড়ে পড়লে এ আকস্মিক বন্যার সৃষ্টি হয়।', 'শেষ খবর পাওয়া পর্যন্ত, নেপাল তিব্বত সীমান্তের দুই দিকেই যৌথ উদ্ধার অভিযান চলছে। এ পর্যন্ত ১২ জনকে জীবিত উদ্ধার করা সম্ভব হয়েছে। তবে চীনের সরকারি সংবাদমাধ্যম জানিয়েছে, তিব্বত অংশে ব্যাপক প্রাণহানির আশঙ্কা করা হচ্ছে। নেপাল কর্তৃপক্ষও বড় ধরনের ক্ষয়ক্ষতির কথা নিশ্চিত করেছে।\r\n\r\nসোশ্যাল মিডিয়া এক্স-এ শেয়ার করা একটি হালনাগাদ তথ্যে নেপাল ট্যুরিজম বোর্ড জানিয়েছে, তারা মোট ৩৮৪ জন পর্যটককে নিখোঁজ হিসেবে শনাক্ত করেছে। এদের মধ্যে ২৯১ জন বিদেশী নাগরিক এবং ৯৩ জন নেপালি নাগরিক। নিখোঁজ বিদেশীদের মধ্যে ১২ জন ব্রিটিশ নাগরিক, ১০৫ জন ভারতীয়, ৩৭ জন অনাবাসী ভারতীয় (এনআরআই), ১৭ জন মালয়েশীয়, ৪ জন দক্ষিণ আফ্রিকান, ৩ জন আমেরিকান, ১ জন অস্ট্রেলীয় এবং ১ জন ডাচ নাগরিক বলে নিশ্চিত হওয়া গেছে। এ ছাড়া আরো ১১১ জন নিখোঁজের জাতীয়তা এখনো নিশ্চিত হওয়া যায়নি।\r\n\r\nনেপাল পুলিশের মুখপাত্র অভি নারায়ণ কাফলে জানান, সেনাবাহিনী, পুলিশ ও অন্যান্য নিরাপত্তা সংস্থা যৌথভাবে উদ্ধারকাজে অংশ নিয়েছে।\r\n\r\nসামাজিক যোগাযোগমাধ্যমে ছড়িয়ে পড়া ভিডিও ফুটেজে দেখা গেছে, পাহাড়ি নদীর প্রচণ্ড স্রোত গ্রামগুলোর ওপর দিয়ে বয়ে যাচ্ছে।\r\n\r\nবন্যা ও ভূমিধসের পর ভোটে কোশি নদীর ভাটিতে অবস্থিত একাধিক এলাকায় সতর্কতা জারি করা হয়েছে। পুরো অঞ্চলের সড়ক যোগাযোগ, বিদ্যুৎ ও টেলিফোন নেটওয়ার্ক সম্পূর্ণ বিচ্ছিন্ন হয়ে পড়েছে। রাজধানী কাঠমান্ডুর সঙ্গে সংযোগকারী প্রধান সড়কটি বন্ধ রয়েছে বলে জানিয়েছে প্রশাসন।', 'কাঠমান্ডুতে অবস্থানরত চীনা ব্যবসায়ী ই লিয়াং জানান, তাদের কোম্পানির সাতটি ট্রাক ওই এলাকায় আটকা পড়েছে, যার সবগুলোর কর্মীরাই নেপালি। সেখানে থাকা কর্মীদের সঙ্গে যোগাযোগ করতে না পারায় অনিশ্চয়তা তৈরি হয়েছে।\r\n\r\nতিনি আরো বলেন, আমার জানা মতে, কোনো পূর্বাভাস দেয়া হয়নি। বিশেষ করে বর্ষাকালে সেখানে মাঝে মাঝে পাহাড় ধস হতো। কিন্তু এবারের ঘটনা অনেক বেশি মারাত্মক মনে হচ্ছে।\r\n\r\nদুর্যোগের কারণে তিব্বত অংশও মারাত্মক ক্ষতিগ্রস্ত হয়েছে। তবে সেখানকার ক্ষয়ক্ষতির পরিমাণ এখনো অস্পষ্ট। সিচুয়ান প্রদেশের বাসিন্দা গুয়ান দাওক্সুয়ানের জানিয়েছেন, বুধবার সকালে তিনি তার স্ত্রীর সঙ্গে যোগাযোগ হারিয়েছেন। তার স্ত্রী তিব্বতে সড়ক ও সেতু নির্মাণের কাজে নিয়োজিত একটি রাষ্ট্রীয় ঠিকাদারি প্রতিষ্ঠানে কাজ করেন। গুয়ান জানান, সড়ক যোগাযোগ বিচ্ছিন্ন হয়ে পড়ায় নেপালি কর্তৃপক্ষ এলাকাটি পরিদর্শনের জন্য একটি হেলিকপ্টার পাঠানোর চেষ্টা করেছিল। কিন্তু প্রবল বাতাসের কারণে সেটি দুর্ঘটনাস্থলে পৌঁছাতে পারছে না।\r\n\r\nএদিকে পরিস্থিতি পর্যালোচনা করতে জরুরি বৈঠক করেছেন নেপালের প্রধানমন্ত্রী বালেন শাহ। তিনি জানান, রেড ক্রস ও স্কাউটসসহ স্থানীয় মেডিকেল টিমগুলোকে কাজে নামানো হয়েছে। দেশটির পররাষ্ট্রমন্ত্রী শিশির খানাল পার্লামেন্টে জানিয়েছেন, নিখোঁজদের মধ্যে পুলিশের ২৬ জন কর্মকর্তা, সশস্ত্র পুলিশের ৯ জন এবং ৪৪ জন সেনাসদস্য রয়েছেন।\r\n\r\nঅন্যদিকে চীনের প্রেসিডেন্ট শি জিনপিং নিখোঁজদের উদ্ধারে সর্বাত্মক তৎপরতা চালানোর নির্দেশ দিয়েছেন। একই সঙ্গে মাধ্যমিক দুর্যোগ এড়াতে পর্যবেক্ষণ ব্যবস্থা শক্তিশালী করা এবং আগাম সতর্ক বার্তা চালুর তাগিদ দিয়েছেন তিনি। চীনা সরকারের পক্ষ থেকেও উদ্ধার ও ত্রাণ কার্যক্রম চালানোর জন্য উদ্ধারকারী দলকে তিব্বতে যাওয়ার নির্দেশ দেয়া হয়েছে।\r\n\r\nগত বছরও তিব্বত অংশের হিমবাহ গলে রসুইয়া এলাকায় আকস্মিক বন্যায় ১৮ জনের মৃত্যু হয়েছিল। তবে স্থানীয় কর্মকর্তাদের মতে, এবারের দুর্যোগের তীব্রতা গত বছরের চেয়ে অনেক বেশি।', 'articles/roSL59nPIdtH2OrRE4h6dr0yvN8j2nMpuPELWkId.jpg', NULL, NULL, NULL, 'বিবিসি', 18, 23, 1, NULL, 'published', 0, 0, 0, '2026-08-26 07:32:17', '2026-08-26 07:32:17', '2026-08-26 07:32:17', NULL),
	(35, 'দেশে সারের ঘাটতি নেই, বাস্তব সংকটের চেয়ে বেশি রটনা হচ্ছে: ত্রাণমন্ত্রী', 'দশ-সরর-ঘটত-নই-বসতব-সকটর-চয়-বশ-রটন-হচছ-তরণমনতর', NULL, 'দুর্যোগ ব্যবস্থাপনা ও ত্রাণমন্ত্রী আসাদুল হাবিব দুলু বলেছেন, দেশে সারের কোনো ঘাটতি নেই।', 'সার নিয়ে যতটা না বাস্তব সংকট, তার চেয়ে বেশি রটনা হচ্ছে। সার বিতরণ ব্যবস্থা গতিশীল করতে প্রতিটি ইউনিয়নে আরো একজন করে ডিলার নিয়োগ দেওয়া হবে বলেও তিনি জানান। আজ বুধবার দুপুরে লালমনিরহাট সদর হাসপাতাল পরিদর্শন ও পর্যালোচনা সভা শেষে সাংবাদিকদের প্রশ্নের জবাবে মন্ত্রী এসব কথা বলেন।', 'আসাদুল হাবিব দুলু বলেন, সরকার কৃষকদের জন্য সারে প্রচুর পরিমাণে ভর্তুকি দিচ্ছে। সার বিতরণে যাতে কোনো ধরনের সমস্যা না হয়, সেজন্য ডিলারের সংখ্যা বাড়ানোর উদ্যোগ নেয়া হয়েছে। প্রতিটি ইউনিয়নে আরো একজন করে ডিলার নিয়োগ দেয়া হবে। একই সঙ্গে খুচরা বিক্রেতার সংখ্যাও বাড়ানো হবে।\r\n\r\nতিনি বলেন, কোনো অসাধু ডিলার সার মজুদ করে কৃত্রিম সংকট তৈরির চেষ্টা করলে তার বিরুদ্ধে কঠোর ব্যবস্থা নেয়া হবে। প্রয়োজনে মোবাইল কোর্ট পরিচালনা করে মজুদ করা সার উদ্ধার করা হবে এবং সংশ্লিষ্টদের বিরুদ্ধে আইনি ব্যবস্থা নেয়া হবে।\r\n\r\nমন্ত্রী আরো বলেন, সার নিয়ে মানুষের মধ্যে অযথা আতঙ্কিত হওয়ার কোনো কারণ নেই। কৃষকের প্রয়োজন অনুযায়ী সার সরবরাহ নিশ্চিত করতে সরকার প্রয়োজনীয় সব পদক্ষেপ নিচ্ছে।\r\n\r\nএর আগে পবিত্র ঈদে মিলাদুন্নবী (সা.) ও জাতীয়তাবাদী স্বেচ্ছাসেবক দলের ৪৬তম প্রতিষ্ঠাবার্ষিকী উপলক্ষ্যে লালমনিরহাট সদর হাসপাতালের রোগীদের উন্নত খাবার বিতরণ কার্যক্রমের উদ্বোধন করেন মন্ত্রী। এ সময় জেলা প্রশাসক রাশেদুল হক, জেলা পরিষদ প্রশাসক একেএম মমিনুল হকসহ স্বাস্থ্য বিভাগের কর্মকর্তারা উপস্থিত ছিলেন।', NULL, 'articles/GIQMmjjnSuEQ6S5q9FpxlwEMpuOBNN5FwEocdE9I.jpg', NULL, NULL, NULL, NULL, 5, 6, 1, NULL, 'published', 0, 1, 2, '2026-08-26 07:37:34', '2026-08-26 07:37:34', '2026-08-29 07:26:19', NULL),
	(36, 'সৌদি প্রো লিগে রেকর্ড রোনালদোর', 'সদ-পর-লগ-রকরড-রনলদর', NULL, 'নিজেকে এমন এক উচ্চতায় নিয়েছেন ক্রিস্টিয়ানো রোনালদো খেলতে নামলেই কোনো না কোনো রেকর্ড গড়েন তিনি। গতকালকের রাতটাও ব্যতিক্রম ছিল না।', 'সৌদি প্রো লিগের ম্যাচ রেকর্ড গড়েছেন রোনালদো। আল নাসরের হয়ে এখন সর্বোচ্চ গোল তার। লিগের ইতিহাসে ট্রান্সফারমার্কেটের তথ্য মতে, আল নাসরের হয়ে তার গোল এখন ১০৪।আল তাওয়ুনের বিপক্ষে গোল করে রেকর্ডটি গড়েছেন রোনালদো। রেকর্ড গড়ার রাতে আল নাসরকে দারুণ এক জয় এনে দিয়েছেন রোনালদো। ৫০ মিনিটে করা তার গোলে ২-১ ব্যবধানের জয় পায় আল নাসর। লিগে টানা চতুর্থ জয়ের আগে অবশ্য ম্যাচে পিছিয়ে পড়েছিল আল নাসর।', 'ম্যাচের ১১ মিনিটে আল তাওয়ুনের গোলে লিড নিয়েছিল বাসেম মোহাম্মদ আলহুরাইজি।\r\nবিরতির আগেই অবশ্য সমতায় ফেরে আল নাসর। প্রথমার্ধের যোগ করা সময়ের পঞ্চম মিনিটে দলকে সমতায় ফেরান রোনালদোরই স্বদেশী সামু কস্তা। পরে জয়সূচক গোল আসে রোনালদোর পা থেকে। যা আবার রেকর্ড গোল।', 'সবমিলিয়ে পেশাদার ফুটবলে ৯৭৮ গোল পেলেন রোনালদো। প্রথম ফুটবলার হিসেবে হাজার গোল করতে ৪১ বছর বয়সী কিংবদন্তি ২২ গোল দূরে। চলতি মৌসুমে আল নাসরের হয়ে দ্বিতীয়। প্রথম গোলটি করেন আল রিয়াদের বিপক্ষে।', 'articles/jAY3tKk2Vd9sYbkxKCZf7AoXhjqi9s8R3g2lDv4Z.jpg', NULL, NULL, NULL, NULL, 1, 2, 1, NULL, 'published', 0, 0, 2, '2026-08-29 00:57:08', '2026-08-29 00:57:08', '2026-08-29 09:33:26', NULL),
	(37, 'আর্জেন্টিনার আবেদনে শাস্তি শিথিল করল ফিফা', 'আরজনটনর-আবদন-শসত-শথল-করল-ফফ', NULL, 'বিশ্বকাপ ফাইনালে স্পেনের খেলোয়াড়দের সঙ্গে সংঘর্ষের ঘটনায় নিষেধাজ্ঞা পাওয়া আর্জেন্টিনার তিন ফুটবলার ও কোচিং স্টাফের এক সদস্যের জন্য কিছুটা স্বস্তির খবর এসেছে।', 'আর্জেন্টাইন ফুটবল অ্যাসোসিয়েশনের (এএফএ) আবেদনের পর নিষেধাজ্ঞা কার্যকরের নিয়মে পরিবর্তন এনেছে ফিফা। লিয়ান্দ্রো পারেদেস, নাহুয়েল মোলিনা ও থিয়াগো আলমাদাকে যথাক্রমে ১০, ৭ ও ১ ম্যাচের জন্য নিষিদ্ধ করা হয়েছিল। কোচিং স্টাফের সদস্য রবার্তো আয়ালাকেও দেওয়া হয় তিন ম্যাচের নিষেধাজ্ঞা।', 'শাস্তির মেয়াদ দ্রুত শেষ করার সুযোগ চেয়ে ফিফার কাছে আবেদন করেছিল এএফএ। তাদের অনুরোধ ছিল, নিষেধাজ্ঞার ম্যাচগুলো যেন ‘এ’ শ্রেণির আন্তর্জাতিক প্রীতি ম্যাচেও গণনা করা হয়। ফিফার ডিসিপ্লিনারি কমিটি সেই আবেদন অনুমোদন করেছে।\r\n\r\nআগের নিয়মে আন্তর্জাতিক উইন্ডোর সব ম্যাচ নিষেধাজ্ঞা কাটানোর ক্ষেত্রে বিবেচিত হতো না। নতুন সিদ্ধান্তের ফলে প্রতিযোগিতামূলক ম্যাচের পাশাপাশি আন্তর্জাতিক প্রীতি ম্যাচেও শাস্তির মেয়াদ পূরণ করতে পারবেন নিষিদ্ধ খেলোয়াড়েরা। এতে চলতি বছরের শেষ দিক ও ২০২৭ সালের শুরুতে বিভিন্ন আন্তর্জাতিক উইন্ডোতে পারেদেস ও মোলিনাদের নিষেধাজ্ঞা দ্রুত শেষ হওয়ার সুযোগ তৈরি হয়েছে।', 'এএফএ অবশ্য এখানেই থামছে না। নিষেধাজ্ঞার মাত্রা কমানোর লক্ষ্যে ফিফার আপিল কমিটির কাছে আবেদন করার প্রস্তুতি নিচ্ছে তারা। রায়ের পূর্ণাঙ্গ নথি হাতে পাওয়ার পর আনুষ্ঠানিকভাবে সেই প্রক্রিয়া শুরু হবে। এএফএর আইনি উপদেষ্টা আন্দ্রেস পাতন এরই মধ্যে নিষেধাজ্ঞাকে মাত্রাতিরিক্ত বলে মন্তব্য করেছেন। ফিফার আপিল প্রক্রিয়ায় সুরাহা না হলে কোর্ট অব আরবিট্রেশন ফর স্পোর্টসের (সিএএস) দ্বারস্থ হওয়ার পথও খোলা রাখছে আর্জেন্টিনা।', 'articles/swZQymVKf6o65EDug4Da3bCG8Vocjgrs6fH7aZnR.webp', NULL, NULL, NULL, NULL, 1, 2, 1, NULL, 'published', 0, 0, 3, '2026-08-29 01:01:49', '2026-08-29 01:01:49', '2026-08-30 20:59:09', NULL),
	(38, 'মার্কিন নিষেধাজ্ঞায় চাপে ইরানের অর্থনীতি', 'মরকন-নষধজঞয়-চপ-ইরনর-অরথনত', NULL, 'যুক্তরাষ্ট্রের সঙ্গে সংঘাতের কারণে ইরানের অর্থনীতিতে ক্ষতির মাত্রা বাড়ছে। দেশটির নেতারাও অর্থনৈতিক সংকটের বিষয়টি স্বীকার করছেন।', 'সর্বোচ্চ নেতা সরকারকে জনগণের দুর্দশা লাঘবে পদক্ষেপ নেওয়ার আহ্বান জানিয়েছেন। অন্যদিকে প্রেসিডেন্ট মাসুদ পেজেশকিয়ান জানিয়েছেন, মার্কিন নিষেধাজ্ঞা ও অবরোধের কারণে ইরানের বৈদেশিক বাণিজ্য প্রায় ৩৫ শতাংশ সংকুচিত হয়েছে।\r\n\r\nএর মধ্যেই ইরানের অন্য নেতারা যুক্তরাষ্ট্রকে সামরিক পাল্টা পদক্ষেপের হুমকি দিচ্ছেন এবং দাবি করছেন, কৌশলগতভাবে গুরুত্বপূর্ণ হরমুজ প্রণালীর ওপর ইরানের নৌবাহিনীর নিয়ন্ত্রণ রয়েছে। বিশ্ব জ্বালানি সরবরাহের অন্যতম গুরুত্বপূর্ণ এই জলপথে চলাচল বাধাগ্রস্ত করার সক্ষমতা ইরানকে কৌশলগত সুবিধা দিচ্ছে।', 'যুদ্ধের ছয় মাস পেরিয়ে যাওয়ার পাশাপাশি আলোচনা অচলাবস্থায় পড়ার মধ্যে মার্কিন প্রেসিডেন্ট ডোনাল্ড ট্রাম্পের প্রশাসন ইরানের ওপর অর্থনৈতিক চাপ আরও বাড়িয়েছে। মার্কিন কর্মকর্তারা এ পদক্ষেপকে ‘অর্থনৈতিক ডি-ডে’ হিসেবে অভিহিত করেছেন।\r\n\r\nওয়াশিংটন বিভিন্ন দেশকে ইরানের সঙ্গে ব্যবসায়িক সম্পর্ক ছিন্ন করার আহ্বান জানিয়েছে। অন্যথায় তাদের ‘সেকেন্ডারি স্যাংশন’ বা পরোক্ষ নিষেধাজ্ঞার মুখে পড়তে হতে পারে বলে সতর্ক করা হয়েছে। তবে ইরানের প্রধান বাণিজ্যিক অংশীদার চীন ও ভারতের বিরুদ্ধে সরাসরি শাস্তিমূলক ব্যবস্থা নেওয়া থেকে বিরত রয়েছে মার্কিন ট্রেজারি বিভাগ। এমন পদক্ষেপ যুক্তরাষ্ট্র ও বিশ্ব অর্থনীতিতে বিরূপ প্রভাব ফেলতে পারে বলে মনে করা হচ্ছে।', 'এরই মধ্যে ইরানের সঙ্গে ব্যবসায়িক লেনদেনের অভিযোগে মিশরের ‘ব্যাংক মিসর’-এর ওপর নিষেধাজ্ঞা আরোপ করেছে মার্কিন ট্রেজারি বিভাগ। একই সঙ্গে সংযুক্ত আরব আমিরাতে ব্যাংকটির শাখাগুলোকে ডলারভিত্তিক লেনদেন থেকে বিচ্ছিন্ন করার একটি নিয়ম প্রস্তাব করা হয়েছে।\r\n\r\nমিশরের কেন্দ্রীয় ব্যাংক জানিয়েছে, তারা ও দেশটির পররাষ্ট্র মন্ত্রণালয় এ বিষয়ে মার্কিন কর্মকর্তাদের সঙ্গে যোগাযোগ করছে। তবে এ পদক্ষেপ শুধু ‘ব্যাংক মিসর ইউএই’-এর করসপন্ডেন্ট ব্যাংকগুলোর সঙ্গে মার্কিন ডলারের লেনদেনের ক্ষেত্রে প্রযোজ্য বলে জানিয়েছে তারা।\r\n\r\nমার্কিন ট্রেজারি বিভাগের ওয়েবসাইটে প্রকাশিত পৃথক এক বিজ্ঞপ্তিতে হংকংভিত্তিক একটি প্রতিষ্ঠান এবং ইরানের ‘ব্যাংক মেলি’র সঙ্গে সংশ্লিষ্ট একজন ব্যক্তির ওপরও নিষেধাজ্ঞা আরোপের কথা জানানো হয়েছে।\r\n\r\nনিষেধাজ্ঞার ধারাবাহিকতার মধ্যে ইরানের অর্থনীতিতে যুদ্ধের নেতিবাচক প্রভাব আরও বেড়েছে। দেশটিতে গত মাসে বার্ষিক মুদ্রাস্ফীতির হার ৬৬ শতাংশে পৌঁছেছিল।', 'articles/U7duruvLyycLSowndIvmaTjzag9Em86S3D6TFhZw.webp', NULL, NULL, 'ইরানের সর্বোচ্চ নেতা মোজতবা খামেনি ও মার্কিন প্রেসিডেন্ট ডোনাল্ড ট্রাম্প', 'অনলাইন', 18, 22, 1, NULL, 'published', 0, 0, 5, '2026-08-29 01:16:10', '2026-08-29 01:16:10', '2026-08-30 22:59:39', NULL),
	(39, 'যাত্রী পরিবহন সক্ষমতা ও সেবা বাড়ালেও বড় বাধা এক রানওয়ে, অপ্রতুল পার্কিং', 'যতর-পরবহন-সকষমত-ও-সব-বড়লও-বড়-বধ-এক-রনওয়-অপরতল-পরক', 'থার্ড টার্মিনাল', 'ঢাকার হযরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে থার্ড টার্মিনাল চালু হলে যাত্রী ব্যবস্থাপনা ও উড়োজাহাজ পরিচালনার সক্ষমতা বাড়বে।', 'একই সঙ্গে বাড়বে ফ্লাইটের চাপ। কিন্তু একটি মাত্র রানওয়ে ও সীমিত পার্কিং সক্ষমতার কারণে নতুন টার্মিনালের বাড়তি সুবিধা পুরোপুরি কাজে লাগানো নিয়ে তৈরি হয়েছে শঙ্কা। বর্তমানে রানওয়ে ব্যস্ত থাকায় উড্ডয়নের আগে ৩০-৪০ মিনিট এবং অবতরণের আগে ২০-৩০ মিনিট পর্যন্ত উড়োজাহাজকে অপেক্ষা করতে হচ্ছে। টার্মিনাল চালুর পর ফ্লাইট সংখ্যা বাড়লে এ সংকট আরো তীব্র হতে পারে। সেক্ষেত্রে শাহজালাল বিমানবন্দরকে আঞ্চলিক এভিয়েশন হাব হিসেবে গড়ে তোলার উদ্যোগও বাধার মুখে পড়তে পারে। একই সঙ্গে নতুন টার্মিনাল হলেও উড়োজাহাজ পার্কিং সুবিধায় এ অঞ্চলের অন্য বিমানবন্দরগুলোর তুলনায় অনেকটাই পিছিয়ে থাকছে ঢাকা।', 'ভারতের ইন্দিরা গান্ধী আন্তর্জাতিক বিমানবন্দর (দিল্লি) কর্তৃপক্ষের তথ্য বলছে, সেখানে ২১০টি ফিজিক্যাল বে রয়েছে। পাশাপাশি ‘মাল্টিপল অ্যাপ্রন রÅvম্প সিস্টেম’-এর দুটি কোড-সি স্ট্যান্ডসহ মোট স্ট্যান্ডের সংখ্যা ২৪০। সিঙ্গাপুরের চাঙ্গি বিমানবন্দর কর্তৃপক্ষের তথ্য অনুযায়ী, সেখানে ১১১টি কন্টাক্ট ও ৭৮টি রিমোট স্ট্যান্ড রয়েছে। সম্প্রসারণকাজ শেষ হলে এ সংখ্যা ২০০ ছাড়িয়ে যাবে। অন্যদিকে ১২০টি পার্কিং বে থাকার পরও থাইল্যান্ডের সুবর্ণভূমি বিমানবন্দরে উড়োজাহাজ পার্কিংয়ের ওপর চাপ রয়েছে। বড় উড়োজাহাজের নির্ধারিত স্ট্যান্ড ও অ্যাপ্রন সংস্কারসহ বিভিন্ন কারণে সেখানে পার্কিং ব্যবস্থাপনায় চ্যালেঞ্জ তৈরি হচ্ছে। এর বিপরীতে শাহজালাল বিমানবন্দরে বর্তমানে উড়োজাহাজ পার্কিং বে রয়েছে ২১টি। থার্ড টার্মিনাল চালু হলে আরো ৩৭টি পার্কিং বে যুক্ত হবে। সব মিলিয়ে পার্কিং বের সংখ্যা হবে ৫৮।', 'জাতীয় পতাকাবাহী বিমান বাংলাদেশ এয়ারলাইনস ২০৩৫ সালের মধ্যে বহরে উড়োজাহাজের সংখ্যা ৪৭টিতে উন্নীত করার পরিকল্পনা নিয়েছে। এরই মধ্যে বোয়িংয়ের সঙ্গে ১৪টি উড়োজাহাজ কেনার চুক্তি করেছে বিমান। প্রথম উড়োজাহাজটি ২০৩১ সালের নভেম্বরে এবং বাকিগুলো ২০৩৫ সালের অক্টোবরের মধ্যে আসার কথা। এয়ারবাসও বিমানকে ১০টি উড়োজাহাজের প্রস্তাব দিয়েছে, যা সংস্থাটি বর্তমানে মূল্যায়ন করছে।\r\n\r\nপরিকল্পনাধীন এসব উড়োজাহাজ বহরে যুক্ত হওয়ার পর ঢাকায় সেগুলো পার্কিংয়ে কোনো সমস্যা হবে না বলে জানিয়েছেন বিমানের ব্যবস্থাপনা পরিচালক ও প্রধান নির্বাহী কর্মকর্তা কাইজার সোহেল আহমেদ। তিনি বণিক বার্তাকে বলেন, ‘নতুন উড়োজাহাজগুলোর হ্যাঙ্গার ও পার্কিংয়ের জন্য আমাদের এখানে পর্যাপ্ত জায়গা রয়েছে। পাশাপাশি ভবিষ্যতে আরো হ্যাঙ্গার তৈরি ও কারিগরি সক্ষমতা বৃদ্ধির পরিকল্পনাও আমাদের রয়েছে।’\r\n\r\nবেসরকারি খাতের ইউএস-বাংলা এয়ারলাইনস ২০২৭ সালের মধ্যে বোয়িং থেকে ২১টি উড়োজাহাজ ভাড়ায় আনার ঘোষণা দিয়েছে। বর্তমানে এয়ারলাইনসটির বহরে ২৫টি উড়োজাহাজ রয়েছে। ঢাকাকে প্রধান হাব হিসেবে ব্যবহার করছে ইউএস-বাংলা। এছাড়া নভোএয়ার এবং এয়ার অ্যাস্ট্রার ফ্লাইটগুলোও শাহজালাল বিমানবন্দরকেন্দ্রিক। অন্যদিকে ঢাকায় বর্তমানে প্রায় ৩০টি বিদেশী এয়ারলাইনস নিয়মিত যাত্রী ও কার্গো ফ্লাইট পরিচালনা করছে।\r\n\r\nসব মিলিয়ে বর্তমানে শাহজালালে প্রতিদিন গড়ে প্রায় ৩০০ উড়োজাহাজ উড্ডয়ন ও অবতরণ করে। জাপান আন্তর্জাতিক সহযোগিতা সংস্থার (জাইকা) প্রক্ষেপণ অনুযায়ী, শাহজালালে দৈনিক উড়োজাহাজ চলাচল ২০২৫ সালে ৩৮১টি, ২০৩০ সালে ৪৫১টি এবং ২০৩৫ সালে ৫৪৮টিতে দাঁড়াতে পারে।\r\n\r\nএমন প্রেক্ষাপটে শাহজালাল আন্তর্জাতিক বিমানবন্দরের পার্কিং সক্ষমতা উদ্বেগের কারণ হয়ে দাঁড়িয়েছে বলে মনে করছেন খাতসংশ্লিষ্টরা। তারা বলছেন, থার্ড টার্মিনাল অ্যাপ্রনে ৩৭টি উড়োজাহাজ রাখার ব্যবস্থা থাকলেও এটিকে পুরো বিমানবন্দরের উড়োজাহাজ পরিচালনার সক্ষমতা হিসেবে দেখার সুযোগ নেই। বাস্তবে কতটি উড়োজাহাজ পরিচালনা করা যাবে, তা রানওয়ে, ট্যাক্সিওয়ে, অ্যাপ্রন, পার্কিং ও উড়োজাহাজের টার্নঅ্যারাউন্ড সময়ের ওপর নির্ভর করবে।', 'articles/UVHpflAHia8aFSHG7RdejTAdlwkiKt8XeF4yIh3i.jpg', NULL, NULL, 'চালুর অপেক্ষায় হযরত শাহজালাল আন্তর্জাতিক বিমানবন্দরের থার্ড টার্মিনাল', NULL, 5, 6, 1, NULL, 'published', 1, 0, 16, '2026-08-30 22:02:30', '2026-08-30 22:02:30', '2026-08-31 00:32:29', NULL);


CREATE TABLE IF NOT EXISTS `article_images` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `article_id` bigint unsigned NOT NULL,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `caption` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` tinyint unsigned NOT NULL DEFAULT '0',
  `is_cover` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `article_images_article_id_sort_order_index` (`article_id`,`sort_order`),
  CONSTRAINT `article_images_article_id_foreign` FOREIGN KEY (`article_id`) REFERENCES `articles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


