INSERT INTO `videos` (`id`, `title`, `slug`, `thumbnail`, `video_url`, `video`, `video_type`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'অক্টোবরে বাংলাদেশের বিপক্ষে ম্যাচ খেলতে চায় ব্রাজিল', 'oktobre-bangladeser-bipkshe-mzac-khelte-cay-brajil', 'thumbnails/lnm61Abn4PqUlzHPglgVZKoym7BfKSXXjLOurgle.png', NULL, 'videos/No5Z4NQ89i9iTF9BsPw69s9WS9Ava38ZOJjCJ9uY.mp4', 'upload', 'আগামী সেপ্টেম্বরের ফিফা উইন্ডো শেষ হবে ৬ অক্টোবর। সেই সময়ের মধ্যেই বাংলাদেশের বিপক্ষে ঢাকার জাতীয় স্টেডিয়ামে একটি প্রীতি ম্যাচ খেলার প্রস্তাব দিয়েছে ব্রাজিল ফুটবল কনফেডারেশন (সিবিএফ)। বাফুফের একটি দায়িত্বশীল সূত্র প্রথম আলোকে এ তথ্য জানিয়েছে।', 1, '2026-08-23 23:58:32', '2026-08-24 01:50:33'),
	(2, 'অক্টোবরে বাংলাদেশের বিপক্ষে ম্যাচ খেলতে চায় ব্রাজিল', 'eer', 'thumbnails/z8q3D6QYWTEp1irm9Xftn0Tsdlhky7aSUA75l0S2.png', NULL, 'videos/22MSMnuDltKf5tgyF868vMSsEDtP2QgzTJIT4fh1.mp4', 'upload', 'wwwwwwwwwwwwwwwww', 1, '2026-08-24 01:54:25', '2026-08-24 06:02:15'),
	(3, 'তত্ত্বীয় পরীক্ষা শেষে ২২ এপ্রিলের মধ্যে সব বিষয়ের ব্যবহারিক পরীক্ষা শেষ করে নম্বর অনলাইনে পাঠাতে হবে।', 'tttweey-preeksha-seshe-22-epriler-mdhze-sb-bishyer-bzbharik-preeksha-sesh-kre-nmbr-onlaine-pathate-hbe', 'thumbnails/Jg10PrNSNPDLKp4SbDAm017ksBQAnMoNNsY5ZVZS.jpg', NULL, 'videos/c88uYKM6TmmcKFlj0Lp2CTHIPrFb0JT7u9roFTO6.mp4', 'upload', 'সোমবার (২৪ আগস্ট) আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটি পরীক্ষার সময়সূচি চূড়ান্ত করে। পরে শিক্ষা মন্ত্রণালয়ের মাধ্যমিক ও উচ্চশিক্ষা বিভাগ তা অনুমোদন করেছে। আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটির সভাপতি ও ঢাকা মাধ্যমিক ও উচ্চমাধ্যমিক শিক্ষা বোর্ডের চেয়ারম্যান অধ্যাপক সৈয়দ আক্তারুজ্জামান বিষয়টি নিশ্চিত করেছেন। তিনি বলেন, ‘১৪ মার্চ থেকে পরীক্ষা শুরু হয়ে এপ্রিলে শেষ হবে।’', 1, '2026-08-24 06:37:41', '2026-08-24 06:37:41'),
	(4, 'সোমবার (২৪ আগস্ট) আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটি পরীক্ষার সময়সূচি চূড়ান্ত করে।', 'sombar-24-agst-antsiksha-bord-smnwy-kmiti-preekshar-smysuuci-cuurant-kre', 'thumbnails/1GxNpYik3hrhZZ6pjzKut5Muv1zSnxuxaNhDUrpl.jpg', NULL, 'videos/POd7PXytQjscspi2thDAjNKXJVXmhJ4hSgnb1yVA.mp4', 'upload', 'সোমবার (২৪ আগস্ট) আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটি পরীক্ষার সময়সূচি চূড়ান্ত করে। পরে শিক্ষা মন্ত্রণালয়ের মাধ্যমিক ও উচ্চশিক্ষা বিভাগ তা অনুমোদন করেছে। আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটির সভাপতি ও ঢাকা মাধ্যমিক ও উচ্চমাধ্যমিক শিক্ষা বোর্ডের চেয়ারম্যান অধ্যাপক সৈয়দ আক্তারুজ্জামান বিষয়টি নিশ্চিত করেছেন। তিনি বলেন, ‘১৪ মার্চ থেকে পরীক্ষা শুরু হয়ে এপ্রিলে শেষ হবে।’', 1, '2026-08-24 06:38:44', '2026-08-24 06:38:44'),
	(5, 'পরীক্ষার্থীদের পরীক্ষা শুরুর অন্তত ৩০ মিনিট আগে পরীক্ষার হলে প্রবেশ', 'preekshartheeder-preeksha-surur-ontt-30-minit-age-preekshar-hle-prbes-kre-nirdharit-asne-bste-hbe', 'thumbnails/wOoocUjaD3H6ZsW3ZZQlRvFqtfD5BI8ZW7DbD2Bj.jpg', NULL, 'videos/noY7WkCWIQEtJ8c905mW4VLE7M1jU7qGfqsaA8uw.mp4', 'upload', 'পরীক্ষার্থীদের পরীক্ষা শুরুর অন্তত ৩০ মিনিট আগে পরীক্ষার হলে প্রবেশ করে নির্ধারিত আসনে বসতে হবে। বহুনির্বাচনী (এমসিকিউ) ও সৃজনশীল বা রচনামূলক পরীক্ষার মধ্যে কোনো বিরতি থাকবে না। পরীক্ষার্থীদের তত্ত্বীয়, বহুনির্বাচনী ও ব্যবহারিক—প্রতিটি অংশে পৃথকভাবে পাস করতে হবে। পরীক্ষা শুরুর অন্তত সাত দিন আগে নিজ নিজ শিক্ষাপ্রতিষ্ঠান থেকে প্রবেশপত্র সংগ্রহ করতে হবে।', 1, '2026-08-24 06:39:40', '2026-08-24 10:27:27'),
	(6, 'সরকারের ছয় মাস, সিপিডির মূল্যায়ন', 'srkarer-chy-mas-sipidir-muulzayn', 'thumbnails/L3qk7x27NBqplE186CX91f2gIwXgTyqtWhzf107v.webp', NULL, 'videos/0z5LB88rL3ETLvLQzJiV9MeLJKG1rLYgmvFqsrvw.mp4', 'upload', 'নতুন সরকারের প্রথম ছয় মাসে অর্থনৈতিক পুনরুদ্ধার কার্যক্রমে নেতিবাচক প্রবণতাই বেশি দেখছে বেসরকারি গবেষণা সংস্থা সেন্টার ফর পলিসি ডায়ালগ (সিপিডি)। প্রধান ৩১টি সূচকের মধ্যে ১৯টিতেই অবনতি হয়েছে। মূল্যস্ফীতি, মাথাপিছু ঋণ, রাজস্ব আদায়, শিল্পে গ্যাস-বিদ্যুৎ সংকটসহ বেশ কয়েকটি গুরুত্বপূর্ণ খাতের পরিস্থিতি উদ্বেগজনক পর্যায়ে রয়েছে।', 1, '2026-08-24 09:49:21', '2026-08-24 09:49:21'),
	(7, 'ইরানকে একঘরে করার ঘোষণা যুক্তরাষ্ট্রের', 'iranke-ekghre-krar-ghoshna-zuktrashtrer', 'thumbnails/8pLaxpk6bYXUyEfdNwvkMKXH3IJCl0c0DRmqb1lw.jpg', NULL, 'videos/BKMQ1ItYiNx4d1nDuDRuDWwDQG98LfUR1ARFdDWS.mp4', 'upload', 'ইরানের বাণিজ্য অংশীদারদের ডলারভিত্তিক লেনদেন থেকে বিচ্ছিন্ন করার হুমকি যুক্তরাষ্ট্রের', 1, '2026-08-24 21:38:00', '2026-08-24 21:38:00'),
	(8, 'ভেনিজুয়েলার তেল ভান্ডার দখল নিচ্ছে যুক্তরাষ্ট্র।', 'venijuzelar-tel-vandar-dkhl-nicche-zuktrashtr', 'thumbnails/Kyt5dSBqZc37yCMgbPFjVbzzJXAG0kdQ5wOrlX6C.png', NULL, 'videos/jji8aUEELJJ6ZwKADbT9FoDkmFKalkAHUJcX2tEM.mp4', 'upload', 'ss', 1, '2026-08-28 23:06:50', '2026-08-28 23:06:50');

